KG_CODE("f:src/autoskill/cli.py","\"\"\"`auto` command-line interface.\n\nShape follows BrowserSkill's lesson: verb-noun subcommands, human-readable by\ndefault and `--json` for machines, with every error carrying an actionable hint.\nAn agent reads the hint far more reliably than it guesses.\n\nThe CLI is a thin client. It discovers the daemon through the endpoint file,\nstarts one if needed, sends a single request and exits.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport os\nimport socket\nimport sys\nimport time\nfrom pathlib import Path\nfrom typing import Any\n\nfrom .client import (AUTO_START, DaemonUnavailable, call, connect, ping,\n                     read_endpoint, start_daemon)\nfrom .daemon import VERSION, home_dir\nfrom .protocol import Method, ProtocolError\n\n\n# --- output ------------------------------------------------------------------\n\ndef emit(resp: dict[str, Any], args: argparse.Namespace,\n         render=None) -> int:\n    if args.json:\n        print(json.dumps(resp, ensure_ascii=False, indent=2))\n        return 0 if resp.get(\"ok\") else 1\n    if not resp.get(\"ok\"):\n        err = resp.get(\"error\") or {}\n        print(f\"error: {err.get('message', 'unknown error')}\", file=sys.stderr)\n        if err.get(\"hint\"):\n            print(f\"hint: {err['hint']}\", file=sys.stderr)\n        refusal = (err.get(\"details\") or {}).get(\"delivery_refusal\") or {}\n        if refusal:\n            print(f\"quiet delivery declined: {refusal.get('code')} ({refusal.get('reason')}); \"\n                  f\"no input was sent\", file=sys.stderr)\n        eff = err.get(\"effect_state\")\n        if eff and eff != \"none\":\n            print(f\"effect_state: {eff}  <- the action may have taken effect; \"\n                  \"inspect before retrying\", file=sys.stderr)\n        return 1\n    result = resp.get(\"result\") or {}\n    if render:\n        render(result)\n    elif result:\n        print(json.dumps(result, ensure_ascii=False, indent=2))\n    return 0\n\n\n# --- renderers ---------------------------------------------------------------\n\ndef _r_observe(r: dict[str, Any]) -> None:\n    print(r.get(\"text\", \"\"))\n    if r.get(\"elapsed_ms\"):\n        print(f\"\\n[{r['ref_count']} refs from {r['node_count']} nodes \"\n              f\"in {r['elapsed_ms']}ms]\")\n\n\ndef _r_extract(r: dict[str, Any]) -> None:\n    print(r.get(\"text\", \"\"))\n    note = []\n    if r.get(\"truncated\"):\n        note.append(f\"truncated at {r.get('chars')} chars; raise --max-chars\")\n    if r.get(\"window\"):\n        note.append(f\"window {r['window']!r}\")\n    if note:\n        print(\"\\n[\" + \"; \".join(note) + \"]\")\n\n\ndef _r_tabs(r: dict[str, Any]) -> None:\n    tabs = r.get(\"tabs\", [])\n    if not tabs:\n        print(\"no tabs open\")\n        return\n    for t in tabs:\n        mark = \"*\" if t.get(\"active\") else \" \"\n        title = (t.get(\"title\") or \"\")[:44]\n        print(f\"{mark} {t['tab_id']:<6} {title:<46} {t.get('url', '')[:90]}\")\n    print(f\"\\n{len(tabs)} tab(s)   * = active   pass --tab-id to any browser verb\")\n\n\ndef _r_windows(r: dict[str, Any]) -> None:\n    rows = r.get(\"windows\", [])\n    if not rows:\n        print(\"no visible windows\")\n        return\n    w = max(len(x[\"process\"] or \"?\") for x in rows)\n    for x in rows:\n        # fx5: CUA's list_windows line carries pid and the window id (impl_.rs:9006-9009).\n        print(f\"{(x['process'] or '?'):<{w}}  pid={x.get('pid') or '?'}  #{x['handle']}  {x['title']}\")\n    print(f\"\\n{len(rows)} window(s)\")\n\n\ndef _r_action(r: dict[str, Any]) -> None:\n    if r.get(\"apps\") is not None and \"count\" in r:\n        # apps inventory: the list IS the answer.\n        print(f\"{r.get('count')} of {r.get('total')} installed programs match\")\n        for a in r.get(\"apps\") or []:\n            print(f\"  [{a.get('cls', '?'):5s}/{a.get('kind', '?'):9s}] \"\n                  f\"{a.get('name', '')}\")\n        for cls, strat in (r.get(\"strategies\") or {}).items():\n            print(f\"how to drive {cls}: {strat}\")\n        return\n    if r.get(\"rows\") is not None and \"total_rows\" in r:\n        # table --show: the rows ARE the answer; print them, newest last.\n        print(f\"{r.get('total_rows')} total row(s) in {r.get('file')}\"\n              + (f\"  ({r['format']})\" if r.get(\"format\") else \"\"))\n        for row in r.get(\"rows\") or []:\n            print(\"  \" + \" | \".join(row))\n        return\n    if r.get(\"destination\") and \"source_format\" in r:\n        # fix-r3 T13: table --export\n        print(f\"exported {r.get('rows')} row(s) from {r.get('file')} ({r.get('source_format')}) \"\n              f\"to {r.get('destination')} ({r.get('format')})\")\n        return\n    eff = r.get(\"effect_state\", \"?\")\n    bits = [f\"ok  effect={eff}\"]\n    if r.get(\"moved\") is not None and \"h\" in (r.get(\"moved\") or {}):\n        m = r[\"moved\"]; t = r.get(\"percent_to\", {})\n        print(f\"ok  effect={r.get('effect_state')}  moved h{m.get('h')} v{m.get('v')}\"\n              f\"  now at h={t.get('h')}% v={t.get('v')}%\")\n        if r.get(\"note\"):\n            print(f\"note: {r['note']}\")\n        return\n    if r.get(\"moved\") is not None:\n        m, t = r[\"moved\"], r[\"to\"]\n        print(f\"ok  effect={r.get('effect_state')}  moved x{m['x']:+d} y{m['y']:+d}\"\n              f\"  now at ({t['x']}, {t['y']})\")\n        if r.get(\"note\"):\n            print(f\"note: {r['note']}\")\n        return\n    for k in (\"target\", \"sent_to\", \"method\", \"actual\", \"keys\", \"path\",\n              \"title\", \"pid\", \"width\", \"height\", \"scale_factor\", \"x\", \"y\",\n              \"summary\"):\n        if r.get(k) is not None:\n            bits.append(f\"{k}={r[k]}\")\n    print(\"  \".join(str(b) for b in bits))\n    if r.get(\"delivery\") == \"interactive-fallback\":\n        why = (r.get(\"fallback_reason\") or {}).get(\"code\", \"?\")\n        print(f\"delivery: quiet route declined ({why}); used real input once and \"\n              f\"returned the screen\")\n    if r.get(\"dialogs\"):\n        for d in r[\"dialogs\"]:\n            print(f\"dialog: {d['type']} {d['message'][:90]!r} -> {d['answered']}\")\n    if r.get(\"note\") and not r.get(\"mismatch\"):\n        print(f\"note: {r['note'][:200]}\")\n    if r.get(\"mismatch\"):\n        print(\"note: the field reformatted the value; read it before correcting\")\n\n\ndef _r_status(r: dict[str, Any]) -> None:\n    print(f\"autoskill {r['version']} (protocol {r['protocol_version']})\")\n    print(f\"pid {r['pid']}  port {r['port']}  up {r['uptime_s']}s\")\n    print(f\"permission mode: {r['permission_mode']}\"\n          + (\"   quiet: on (stays out of your way)\" if r.get(\"quiet\")\n             else \"   quiet: OFF (raises windows while it works)\"))\n    if r.get(\"idle_timeout_s\"):\n        print(f\"idle timeout: {r['idle_timeout_s']:.0f}s\")\n    reaped = r.get(\"reaped_on_startup\") or {}\n    if reaped.get(\"reaped\"):\n        print(f\"reaped {reaped['reaped']} orphaned browser(s) on startup\")\n    print(f\"home: {r['home']}\")\n    rc = r.get(\"run_control\") or {}\n    if rc:\n        print(f\"Kgrow.io: {rc.get('state')}\"\n              + (f\", run: {rc['run']}\" + (f\" {rc['name']}\" if rc.get(\"name\") else \"\") if rc.get(\"run\") else \", no run\")\n              + (f\", repeat {rc['repeat']}\" if rc.get(\"repeat\", 1) != 1 else \"\")\n              + (\", always allow on\" if rc.get(\"always_allow\") else \"\")\n              + (\", dashboard open\" if rc.get(\"dashboard_open\") else \", dashboard closed\"))\n    ss = r.get(\"sessions\") or []\n    print(f\"sessions: {len(ss)}\")\n    for s in ss:\n        print(f\"  {s['session_id']}  refs={s['refs']}  age={s['age_s']}s\"\n              f\"  idle={s.get('idle_s', 0)}s\")\n    pend = r.get(\"pending_confirmations\") or []\n    if pend:\n        print(f\"\\npending approvals: {len(pend)}\")\n        for p in pend:\n            print(f\"  [{p['token']}] {p['detail']}\")\n        print(\"approve with: auto approve <token>   (deny: auto deny <token>)\")\n\n\n# --- parser ------------------------------------------------------------------\n\ndef build_parser() -> argparse.ArgumentParser:\n    p = argparse.ArgumentParser(\n        prog=\"auto\",\n        description=\"Agent-driven desktop and browser automation.\")\n    p.add_argument(\"--json\", action=\"store_true\", help=\"machine-readable output\")\n    p.add_argument(\"--session\", help=\"session id (most commands need it)\")\n    p.add_argument(\"--version\", action=\"version\", version=f\"autoskill {VERSION}\")\n    sub = p.add_subparsers(dest=\"cmd\", required=True)\n\n    d = sub.add_parser(\"daemon\", help=\"daemon lifecycle\").add_subparsers(\n        dest=\"sub\", required=True)\n    d.add_parser(\"run\", help=\"run in the foreground\")\n    d.add_parser(\"stop\", help=\"shut the daemon down\")\n\n    sub.add_parser(\"status\", help=\"daemon and session status\")\n    sub.add_parser(\"doctor\", help=\"health check with actionable hints\")\n    pth = sub.add_parser(\"path\", help=\"saved paths, recalled only by exact name \"\n                         \"(#paths lists them, #path NAME runs one)\").add_subparsers(dest=\"pathsub\", required=True)\n    pth.add_parser(\"list\", help=\"every saved path: recorded site recipes and queue profiles\")\n    pths = pth.add_parser(\"show\", help=\"one saved path and its steps\")\n    pths.add_argument(\"name\", help=\"the exact name\")\n    pths.add_argument(\"--site\", help=\"the site, when the name is saved on more than one\")\n    pthr = pth.add_parser(\"run\", help=\"run the saved path with exactly this name\")\n    pthr.add_argument(\"name\", help=\"the exact name; a near miss is never run\")\n    pthr.add_argument(\"--site\", help=\"the site, when the name is saved on more than one\")\n    pthr.add_argument(\"--dry-run\", action=\"store_true\", help=\"read and plan without pressing anything\")\n    pthr.add_argument(\"--allow-irreversible\", action=\"store_true\",\n                      help=\"also run steps recorded as irreversible (approvals, submits, downloads)\")\n    pthr.add_argument(\"--max-items\", type=int, help=\"queue profiles: stop after this many items\")\n    pthr.add_argument(\"--repeat\", type=int,\n                      help=\"run the path this many times (default: the repeat set in the Kgrow.io dashboard)\")\n    pthr.add_argument(\"--tab-id\", type=int)\n    pthr.add_argument(\"--text\", action=\"append\", default=[], metavar=\"ROLE|NAME=VALUE\",\n                      help=\"recipes: replace a typed value\")\n    db = sub.add_parser(\"dashboard\", help=\"Kgrow.io: open the live dashboard window (it also opens \"\n                        \"by itself when a flow runs)\")\n    db.add_argument(\"--install\", action=\"store_true\",\n                    help=\"write the Kgrow.io shortcuts (Desktop, Start menu, project folder) and exit\")\n    db.add_argument(\"--reason\", default=\"owner\", help=argparse.SUPPRESS)\n    db.add_argument(\"--no-window\", action=\"store_true\",\n                    help=\"serve the dashboard without opening a window (prints its address)\")\n    rc = sub.add_parser(\"run\", help=\"the dashboard's run controls from a terminal: \"\n                        \"state, pause, resume, stop, clean, save\").add_subparsers(dest=\"runsub\", required=True)\n    rc.add_parser(\"state\", help=\"whether a run is going, paused or stopped, and what waits for you\")\n    rc.add_parser(\"pause\", help=\"hold every next step until resume\")\n    rc.add_parser(\"resume\", help=\"continue after pause or stop\")\n    rc.add_parser(\"stop\", help=\"stop now: refuse every next step, decline waiting approvals and end every \"\n                               \"flow process, program, watchdog, session and window the run opened\")\n    rc.add_parser(\"clean\", help=\"after stop, or when the run has ended: end what the run left running and clear the dashboard\")\n    rc.add_parser(\"reset\", help=\"the old name of clean\")\n    rcs = rc.add_parser(\"save\", help=\"save the current (or last) run into the tool's memory under this name \"\n                                     \"(#path NAME runs it)\")\n    rcs.add_argument(\"name\")\n    rcr = rc.add_parser(\"repeat\", help=\"how many times the next saved paths run (the dashboard's repeat)\")\n    rcr.add_argument(\"count\", type=int)\n    rl = sub.add_parser(\"relocate\", help=\"check, or repair after a move, the links \"\n                        \"that point into this project folder\")\n    rlm = rl.add_mutually_exclusive_group()\n    rlm.add_argument(\"--apply\", action=\"store_true\",\n                     help=\"repair links that still name a former or missing location\")\n    rlm.add_argument(\"--prepare\", action=\"store_true\",\n                     help=\"before moving the folder: stop the daemon and list what still runs from it\")\n\n    s = sub.add_parser(\"session\", help=\"sessions\").add_subparsers(\n        dest=\"sub\", required=True)\n    ss = s.add_parser(\"start\", help=\"start a session on the saved memory, \"\n                      \"a saved memory space, or a new empty one\")\n    ssm = ss.add_mutually_exclusive_group()\n    ssm.add_argument(\"--memory\", metavar=\"NAME\",\n                     help=\"load the saved memory space NAME (pages and click \"\n                          \"methods learned before; the steps still come from you)\")\n    ssm.add_argument(\"--new-memory\", metavar=\"NAME\",\n                     help=\"start an empty memory space NAME; what this \"\n                          \"session learns is kept there alone\")\n    sp = s.add_parser(\"stop\")\n    sp.add_argument(\"id\")\n    sl = s.add_parser(\"list\")\n    sl.add_argument(\"--limit\", type=int, default=100)\n    sl.add_argument(\"--cursor\")\n    s.add_parser(\"memories\", help=\"list the saved memory spaces\")\n\n    w = sub.add_parser(\"windows\", help=\"list open windows\")\n    w.add_argument(\"--all\", action=\"store_true\", help=\"include hidden windows\")\n\n    o = sub.add_parser(\"observe\", help=\"semantic tree of a window with @eN refs\")\n    o.add_argument(\"--window\", help=\"title substring (default: active window)\")\n    o.add_argument(\"--all\", action=\"store_true\", help=\"include offscreen elements\")\n    o.add_argument(\"--max-nodes\", type=int, default=1500)\n    o.add_argument(\"--max-depth\", type=int, default=28)\n    o.add_argument(\"--no-screenshot\", action=\"store_true\",\n                   help=\"tree only (CUA's cheap re-index path); by default \"\n                        \"an observe also takes a grounding screenshot\")\n    o.add_argument(\"--query\", help=\"CUA's projection: only elements matching this text\")\n\n    ex = sub.add_parser(\"extract\",\n                        help=\"reading-order text of a window (no tree)\")\n    ex.add_argument(\"--window\", help=\"title substring (default: active window)\")\n    ex.add_argument(\"--max-chars\", type=int, default=20000)\n\n    c = sub.add_parser(\"click\")\n    c.add_argument(\"ref\")\n    c.add_argument(\"--double\", action=\"store_true\")\n    c.add_argument(\"--right\", action=\"store_true\")\n    c.add_argument(\"--real\", action=\"store_true\",\n                   help=\"real mouse click at coordinates; use when a dialog \"\n                        \"button ignores the normal click\")\n    c.add_argument(\"--count\", type=int, choices=(1, 2, 3))\n    c.add_argument(\"--button\", choices=(\"left\", \"right\", \"middle\"))\n    c.add_argument(\"--modifier\", action=\"append\",\n                   help=\"a key held during the click (repeatable)\")\n    c.add_argument(\"--delivery-mode\", choices=(\"background\", \"foreground\"),\n                   help=\"CUA's delivery; foreground needs the owner's interactive policy\")\n    c.add_argument(\"--action\", choices=(\"expand\",),\n                   help=\"CUA's click action: expand opens the element (e.g. a split button's \"\n                        \"dropdown) through UIA ExpandCollapsePattern\")\n\n    t = sub.add_parser(\"type\", help=\"type text (optionally into a ref)\")\n    t.add_argument(\"text\")\n    t.add_argument(\"--ref\")\n    t.add_argument(\"--window\", help=\"aim at this window first (#handle or title)\")\n    t.add_argument(\"--method\", default=\"auto\",\n                   choices=[\"auto\", \"value\", \"clipboard\", \"keys\"],\n                   help=\"entry mechanism; auto picks the most reliable\")\n    # B8: CUA type_text.delay_ms - ms between characters (CUA's own\n    # 0..200/default-30 applies inside CUA; argparse type=int is presence/\n    # type only, no range - R10). Absent flag -> None -> omitted on the wire.\n    t.add_argument(\"--delay-ms\", type=int,\n                   help=\"milliseconds between characters (keys rung paces \"\n                        \"per key; value/clipboard are atomic)\")\n    t.add_argument(\"--x\", type=float, help=\"with --window: window-local screenshot X of the field\")\n    t.add_argument(\"--y\", type=float)\n    t.add_argument(\"--delivery-mode\", choices=(\"background\", \"foreground\"),\n                   help=\"CUA's delivery; foreground needs the owner's interactive policy\")\n\n    k = sub.add_parser(\"key\", help=\"press a key or combo, e.g. Ctrl+S\")\n    k.add_argument(\"keys\")\n    k.add_argument(\"--ref\")\n    k.add_argument(\"--window\", help=\"aim at this window first (#handle or title)\")\n    k.add_argument(\"--x\", type=float, help=\"with --window: window-local screenshot X of the target\")\n    k.add_argument(\"--y\", type=float)\n    k.add_argument(\"--delivery-mode\", choices=(\"background\", \"foreground\"),\n                   help=\"CUA's delivery; foreground needs the owner's interactive policy\")\n\n    sv = sub.add_parser(\"set-value\", help=\"set a field's value directly\")\n    sv.add_argument(\"ref\")\n    sv.add_argument(\"--value\", required=True)\n    sv.add_argument(\"--delivery-mode\", choices=(\"background\", \"foreground\"),\n                   help=\"CUA's delivery; foreground needs the owner's interactive policy\")\n\n    f = sub.add_parser(\"focus\")\n    f.add_argument(\"ref\", nargs=\"?\")\n    f.add_argument(\"--window\")\n\n    sc = sub.add_parser(\"scroll\")\n    sc.add_argument(\"--ref\")\n    sc.add_argument(\"--direction\", default=\"down\",\n                    choices=[\"up\", \"down\", \"left\", \"right\"])\n    sc.add_argument(\"--amount\", type=int, default=3)\n    sc.add_argument(\"--by\", default=\"line\", choices=[\"line\", \"page\"])\n    sc.add_argument(\"--window\")\n    sc.add_argument(\"--x\", type=float)\n    sc.add_argument(\"--y\", type=float)\n    sc.add_argument(\"--delivery-mode\", choices=(\"background\", \"foreground\"),\n                   help=\"CUA's delivery; foreground needs the owner's interactive policy\")\n\n    # b11: CUA's drag - pixel-only (a ref maps through a fresh capture;\n    # window pixels pass through; no window = screen-absolute real input).\n    # modifier is deliberately absent (CUA admits and ignores it on Windows).\n    dr = sub.add_parser(\"drag\",\n                        help=\"press-drag-release between two points\")\n    dr.add_argument(\"--ref\", help=\"a driver ref to drag from\")\n    dr.add_argument(\"--to-ref\", help=\"a ref to drop on\")\n    dr.add_argument(\"--window\", help=\"target window (#handle or title)\")\n    for flag in (\"from\", \"to\"):\n        dr.add_argument(f\"--{flag}-x\", type=float)\n        dr.add_argument(f\"--{flag}-y\", type=float)\n    dr.add_argument(\"--button\", choices=[\"left\", \"right\", \"middle\"])\n    dr.add_argument(\"--duration-ms\", type=int,\n                    help=\"wall-clock path budget 0..10000 (CUA default 500)\")\n    dr.add_argument(\"--steps\", type=int,\n                    help=\"interpolated moves 1..200 (CUA default 20)\")\n    dr.add_argument(\"--from-zoom\", action=\"store_true\",\n                    help=\"coordinates are in the last zoom image\")\n    dr.add_argument(\"--delivery-mode\", choices=(\"background\", \"foreground\"),\n                   help=\"CUA's delivery; foreground needs the owner's interactive policy\")\n\n    # B18: CUA's set_window_frame - one exact frame, all six keys\n    # required (the contract's required list; the daemon gate enforces\n    # presence too). Geometry validation is the driver's (R10).\n    sf = sub.add_parser(\"set-window-frame\",\n                        help=\"set a window's exact position and size\")\n    sf.add_argument(\"--pid\", type=int, required=True)\n    sf.add_argument(\"--window-id\", type=int, required=True)\n    sf.add_argument(\"--x\", type=float, required=True)\n    sf.add_argument(\"--y\", type=float, required=True)\n    sf.add_argument(\"--width\", type=float, required=True)\n    sf.add_argument(\"--height\", type=float, required=True)\n\n    # B21: CUA's get_accessibility_tree - a BARE snapshot subcommand (the\n    # verb takes no parameters; the per-window tree is `observe`).\n    sub.add_parser(\"accessibility-tree\",\n                   help=\"one desktop snapshot: processes + top-level windows\")\n    sub.add_parser(\"screen-size\", help=\"primary display geometry in physical pixels\")\n    sub.add_parser(\"cursor-position\", help=\"current OS cursor position\")\n    mc = sub.add_parser(\"move-cursor\", help=\"move the real OS pointer (desktop scope)\")\n    mc.add_argument(\"--x\", type=float, required=True)\n    mc.add_argument(\"--y\", type=float, required=True)\n    mc.add_argument(\"--scope\", choices=[\"desktop\"], default=\"desktop\")\n\n    ss = sub.add_parser(\"screenshot\")\n    ss.add_argument(\"--out\")\n    ss.add_argument(\"--ref\")\n    ss.add_argument(\"--window\")\n\n    zm = sub.add_parser(\"zoom\", help=\"magnify a window region (JPEG)\")\n    zm.add_argument(\"--window-id\", type=int, required=True)\n    zm.add_argument(\"--pid\", type=int)\n    zm.add_argument(\"--x1\", type=float, required=True)\n    zm.add_argument(\"--y1\", type=float, required=True)\n    zm.add_argument(\"--x2\", type=float, required=True)\n    zm.add_argument(\"--y2\", type=float, required=True)\n    zm.add_argument(\"--out\")\n\n    oa = sub.add_parser(\"open-app\", help=\"launch an application\")\n    oa.add_argument(\"command\")\n    # tf: accumulates, so `--args=--new-window` carries a dash value into CUA's additional_arguments array.\n    oa.add_argument(\"--args\", nargs=\"*\", action=\"extend\")\n    oa.add_argument(\"--wait-title\", help=\"wait until a window title matches\")\n    oa.add_argument(\"--timeout\", type=float, default=20)\n    oa.add_argument(\"--start-minimized\", action=\"store_true\")\n    oa.add_argument(\"--url\", action=\"append\", dest=\"urls\")\n\n    ww = sub.add_parser(\"wait-window\", help=\"wait for a window to appear/vanish\")\n    ww.add_argument(\"window\"); ww.add_argument(\"--timeout\", type=float, default=20)\n    ww.add_argument(\"--gone\", action=\"store_true\", help=\"wait until it disappears\")\n    wr = sub.add_parser(\"wait-for\", help=\"wait for an element by name\")\n    wr.add_argument(\"name\"); wr.add_argument(\"--window\")\n    wr.add_argument(\"--timeout\", type=float, default=20)\n\n    cw = sub.add_parser(\"close-window\")\n    cw.add_argument(\"window\")\n\n    qa = sub.add_parser(\"quit-app\",\n                        help=\"close an app's windows, then end its processes\")\n    qa.add_argument(\"process\", nargs=\"?\", default=\"\", help=\"process name, e.g. WINWORD.EXE\")\n    qa.add_argument(\"--pid\", type=int, help=\"force-end this process id instead of matching a name\")\n    qa.add_argument(\"--timeout\", type=float, default=12,\n                    help=\"seconds to wait for a graceful exit before forcing\")\n\n    im = sub.add_parser(\"invoke-menu\",\n                        help=\"invoke an exact native menu item by path\")\n    im.add_argument(\"--window-id\", type=int, required=True)\n    im.add_argument(\"--pid\", type=int, required=True)\n    im.add_argument(\"--path\", nargs=\"+\", required=True,\n                    metavar=\"LABEL\", help=\"menu labels, e.g. File \\\"Save As...\\\"\")\n\n    cr = sub.add_parser(\"clipboard-read\",\n                        help=\"list clipboard formats; --include-text also \"\n                             \"returns the text\")\n    cr.add_argument(\"--include-text\", action=\"store_true\",\n                    help=\"include the clipboard text in the reply\")\n\n    # B19: the three value flags are deliberately NOT a mutually-exclusive\n    # argparse group and none is required - exactly-one is the driver's own\n    # check (R10); an empty or over-supplied call parses and the driver's\n    # verbatim refusal answers.\n    cw = sub.add_parser(\"clipboard-write\",\n                        help=\"replace the clipboard with exactly one of \"\n                             \"--text, --image-path or --file-path\")\n    cw.add_argument(\"--text\", help=\"the text to place on the clipboard\")\n    cw.add_argument(\"--image-path\", help=\"absolute path of an image file\")\n    cw.add_argument(\"--file-path\", help=\"absolute path of a file (file URL)\")\n\n    # B20: --expect takes one JSON predicate per flag (repeatable). The\n    # parser validates NOTHING inside a predicate (R10): a semantically\n    # invalid predicate parses here and the driver's verbatim refusal\n    # answers. timeout_ms/stable_samples pass through with CUA's defaults.\n    vs = sub.add_parser(\"verify-state\",\n                        help=\"verify bounded predicates against one exact \"\n                             \"window; status is satisfied/unsatisfied/unknown \"\n                             \"- unknown is never success\")\n    vs.add_argument(\"--pid\", type=int, required=True)\n    vs.add_argument(\"--window-id\", type=int, required=True)\n    vs.add_argument(\"--expect\", action=\"append\", required=True, metavar=\"JSON\",\n                    help='a predicate object, e.g. '\n                         '\\'{\"window\": {\"exists\": true}}\\' (repeatable)')\n    vs.add_argument(\"--timeout-ms\", type=int,\n                    help=\"polling bound in ms (0..10000, driver default 5000)\")\n    vs.add_argument(\"--stable-samples\", type=int,\n                    help=\"consecutive satisfied samples (1..5, driver default 2)\")\n    vs.add_argument(\"--include-screenshot\", action=\"store_true\",\n                    help=\"attach the final screenshot as uninterpreted evidence\")\n\n    cp = sub.add_parser(\"copy\",\n                        help=\"copy files/folders with Explorer semantics\")\n    cp.add_argument(\"paths\", nargs=\"+\", metavar=\"SRC\",\n                    help=\"one or more sources; the LAST path is the destination\")\n\n    aps = sub.add_parser(\"apps\", help=\"inventory installed programs\")\n    aps.add_argument(\"--find\", help=\"substring filter, e.g. --find power\")\n    aps.add_argument(\"--class\", dest=\"klass\",\n                     help=\"filter by automation class: win32 or uwp\")\n    app_parser = sub.add_parser(\"app\", help=\"what the tool has learned \"\n                                \"about each desktop app\")\n    app_parser.add_argument(\"--memory\", metavar=\"NAME\", default=\"default\",\n                            help=\"memory space to read or teach (default: the saved memory)\")\n    apg = app_parser.add_subparsers(dest=\"appsub\", required=True)\n    apk = apg.add_parser(\"know\", help=\"learn an app: observe it locally, \"\n                         \"research it publicly, remember both\")\n    apk.add_argument(\"exe\", help=\"process name, e.g. winword.exe\")\n    apsh = apg.add_parser(\"show\", help=\"one app's knowledge\")\n    apsh.add_argument(\"exe\", help=\"process name, e.g. winword.exe\")\n    apg.add_parser(\"list\", help=\"every app with knowledge\")\n    mind_parser = sub.add_parser(\"mind\", help=\"cross-memory intelligence: \"\n                                 \"recall anything the tool has learned\")\n    mind_parser.add_argument(\"--memory\", metavar=\"NAME\", default=\"default\",\n                             help=\"memory space to recall from (default: the saved memory)\")\n    mnd = mind_parser.add_subparsers(dest=\"mindsub\", required=True)\n    mrc = mnd.add_parser(\"recall\", help=\"free-text recall across all \"\n                         \"memories (sites, apps, sessions)\")\n    mrc.add_argument(\"query\")\n    mrc.add_argument(\"--k\", type=int, default=5, help=\"how many memories\")\n    mnd.add_parser(\"stats\", help=\"what the mind holds\")\n    mnd.add_parser(\"families\", help=\"cluster sites/apps into lookalike \"\n                   \"families for knowledge transfer\")\n    mnt = mnd.add_parser(\"note\", help=\"tell the mind a recalled memory \"\n                         \"helped or misled (learning)\")\n    mnt.add_argument(\"doc_id\")\n    mnt.add_argument(\"outcome\", choices=[\"ok\", \"fail\"])\n    stp = sub.add_parser(\"setup\", help=\"verify/fix the runtime environment\")\n    stp.add_argument(\"--fix\", action=\"store_true\",\n                     help=\"let the agent install missing Python packages\")\n    rp = sub.add_parser(\"report\", help=\"generate a rich .docx document\")\n    rp.add_argument(\"file\")\n    rp.add_argument(\"--title\")\n    rp.add_argument(\"--block\", action=\"append\", default=[],\n                    help=\"ordered: h1:|h2:|h3:|p:|bullet:|number:|table:\")\n    tb = sub.add_parser(\"table\",\n                        help=\"append rows to ONE persistent ledger (JSON Lines by default, or .csv/.xlsx); \"\n                             \"--show reads any table file; --export DEST writes a copy\")\n    tb.add_argument(\"file\")\n    tb.add_argument(\"--header\",\n                    help=\"column header (required when creating the file)\")\n    tb.add_argument(\"--row\", action=\"append\", default=[],\n                    help=\"one row; columns separated by tabs (or --sep)\")\n    tb.add_argument(\"--sep\", default=\"\\t\", help=\"column separator (default tab)\")\n    tb.add_argument(\"--dedup\", metavar=\"COLS\",\n                    help=\"1-based columns that must be unique together, e.g. 1,2\")\n    tb.add_argument(\"--show\", action=\"store_true\", help=\"read rows back (any table file)\")\n    tb.add_argument(\"--export\", metavar=\"DEST\",\n                    help=\"write the table to a NEW file: .jsonl (or no extension), .csv, .xlsx or .json\")\n    tb.add_argument(\"--limit\", type=int, default=50)\n\n    b = sub.add_parser(\"browser\", help=\"browser automation\").add_subparsers(\n        dest=\"sub\", required=True)\n    bo = b.add_parser(\"open\", help=\"launch the dedicated automation browser\")\n    bo.add_argument(\"--url\")\n    bo.add_argument(\"--headless\", action=\"store_true\")\n    bo.add_argument(\"--browser\",\n                    help=\"chrome|edge|brave|vivaldi|opera|chromium, \"\n                         \"or a full path to any Chromium browser\")\n    bn = b.add_parser(\"navigate\"); bn.add_argument(\"url\")\n    bob = b.add_parser(\"observe\")\n    bob.add_argument(\"--max-nodes\", type=int, default=2500)\n    bob.add_argument(\"--max-tokens\", type=int,\n                     help=\"cap the observation by context cost\")\n    bc = b.add_parser(\"click\"); bc.add_argument(\"ref\"); bc.add_argument(\"--clicks\", type=int, default=1)\n    bt = b.add_parser(\"type\"); bt.add_argument(\"text\"); bt.add_argument(\"--ref\")\n    bt.add_argument(\"--clear\", action=\"store_true\")\n    bk = b.add_parser(\"key\"); bk.add_argument(\"key\")\n    bs = b.add_parser(\"scroll\", help=\"scroll the page (down/right positive)\")\n    bs.add_argument(\"--delta-y\", type=int, default=None,\n                    help=\"positive = down, negative = up\")\n    bs.add_argument(\"--delta-x\", type=int, default=None,\n                    help=\"positive = right, negative = left\")\n    bss = b.add_parser(\"screenshot\"); bss.add_argument(\"--out\")\n    bss.add_argument(\"--full-page\", action=\"store_true\")\n    bss.add_argument(\"--lazy\", action=\"store_true\",\n                     help=\"scroll first so lazy content renders\")\n    b.add_parser(\"close\")\n    bsel = b.add_parser(\"select\", help=\"choose an option in a native <select>\")\n    bsel.add_argument(\"ref\"); bsel.add_argument(\"--value\"); bsel.add_argument(\"--label\")\n    bb = b.add_parser(\"back\", help=\"go back in history\")\n    bb.add_argument(\"--delta\", type=int, default=-1)\n    b.add_parser(\"reload\")\n    bh = b.add_parser(\"hover\", help=\"reveal hover-only menus\"); bh.add_argument(\"ref\")\n    bgh = b.add_parser(\"get-html\", help=\"exact markup\")\n    bgh.add_argument(\"--ref\"); bgh.add_argument(\"--max-chars\", type=int, default=200000)\n    bex = b.add_parser(\"extract\", help=\"structured page data\")\n    bex.add_argument(\"kind\", choices=[\"text\", \"links\", \"tables\", \"title\", \"meta\"])\n    bex.add_argument(\"--ref\"); bex.add_argument(\"--max-chars\", type=int, default=20000)\n    bpop = b.add_parser(\"popups\", help=\"URLs captured from window.open\")\n    bpop.add_argument(\"--clear\", action=\"store_true\")\n    b.add_parser(\"list\", help=\"Chromium browsers installed here\")\n    bcon = b.add_parser(\"console\", help=\"captured console/log entries\")\n    bcon.add_argument(\"--limit\", type=int, default=50)\n    bd = b.add_parser(\"dialog\", help=\"how to answer JavaScript dialogs\")\n    bd.add_argument(\"policy\", choices=[\"dismiss\", \"accept\"])\n    bw = b.add_parser(\"wait\", help=\"wait for the page (or text) to be ready\")\n    bw.add_argument(\"--text\"); bw.add_argument(\"--timeout\", type=float, default=20)\n\n    bt_sub = b.add_parser(\"tab\", help=\"work with multiple tabs\").add_subparsers(\n        dest=\"tabsub\", required=True)\n    btn = bt_sub.add_parser(\"new\", help=\"open a new tab and make it active\")\n    btn.add_argument(\"--url\", help=\"initial URL (default about:blank)\")\n    bt_sub.add_parser(\"list\", help=\"open tabs with their id, title and url\")\n    bts = bt_sub.add_parser(\"select\", help=\"make a tab the active one\")\n    bts.add_argument(\"tab_id\")\n    btc = bt_sub.add_parser(\"close\", help=\"close a tab (default: last opened)\")\n    btc.add_argument(\"tab_id\", nargs=\"?\")\n\n    bm = b.add_parser(\"more\", help=\"continue a --max-tokens observation\")\n    bm.add_argument(\"cursor\", nargs=\"?\",\n                    help=\"line cursor from the previous @more marker\")\n    bm.add_argument(\"--max-tokens\", type=int, default=3000)\n\n    # Every verb that acts on a page accepts --tab-id; BrowserSkill passed a\n    # tab selector on 84% of its commands, because keeping several pages open\n    # beats navigating back and forth through one.\n    for _p in (bn, bob, bc, bt, bk, bs, bss, bsel, bb, bh, bgh, bex, bpop,\n               bcon, bd, bw, bm):\n        _p.add_argument(\"--tab-id\",\n                        help=\"act on this tab instead of the active one\")\n\n    rh = sub.add_parser(\"request-help\", help=\"ask the user to do a step\")\n    rh.add_argument(\"--prompt\", required=True)\n    rh.add_argument(\"--timeout\", type=int, default=180)\n\n    rb = sub.add_parser(\n        \"rb\", help=\"drive the user's REAL signed-in browser through the \"\n                   \"autoskill extension (the Google-safe route)\").add_subparsers(\n        dest=\"rbsub\", required=True)\n    rbe = rb.add_parser(\"ensure\", help=\"discover browser prerequisites for automatic AutoSkill setup\")\n    rbe.add_argument(\"--browser\", choices=[\"edge\", \"chrome\", \"chromium\"], required=True)\n    rbe.add_argument(\"--profile\", type=Path, help=\"Exact browser profile directory when needed\")\n    rbi = rb.add_parser(\"install\", help=\"register the native host (needs the \"\n                                        \"extension id from chrome://extensions)\")\n    rbi.add_argument(\"extension_id\")\n    from .contracts.native_host import HostBrowser\n    rbi.add_argument(\"--browser\", choices=[b.value for b in HostBrowser], default=\"chrome\")\n    rbu = rb.add_parser(\"uninstall\")\n    rbu.add_argument(\"--browser\", choices=[b.value for b in HostBrowser], default=\"chrome\")\n    rb.add_parser(\"status\", help=\"is the bridge connected\")\n    rb.add_parser(\"tabs\", help=\"list the user's open tabs\")\n    rbo = rb.add_parser(\"open\", help=\"open a tab in the user's browser\")\n    rbo.add_argument(\"url\")\n    rba = rb.add_parser(\"activate\", help=\"bring a tab to the front\")\n    rba.add_argument(\"--tab-id\", type=int)\n    rbn = rb.add_parser(\"navigate\", help=\"point an existing tab at a url\")\n    rbn.add_argument(\"url\"); rbn.add_argument(\"--tab-id\", type=int)\n    rbb = rb.add_parser(\"observe\", help=\"semantic tree with @eN refs\")\n    rbb.add_argument(\"--tab-id\", type=int)\n    rbb.add_argument(\"--max-tokens\", type=int,\n                     help=\"cap the observation by context cost\")\n    rbb.add_argument(\"--no-fallback\", action=\"store_true\",\n                     help=\"fail instead of reading the page by OCR when its \"\n                          \"accessibility tree cannot be read\")\n    rbb.add_argument(\"--ocr\", action=\"store_true\",\n                     help=\"also add what is drawn when the tree misses most \"\n                          \"of it (a tree that answers without the page)\")\n    rbc = rb.add_parser(\"click\"); rbc.add_argument(\"ref\")\n    rbc.add_argument(\"--tab-id\", type=int)\n    rbt = rb.add_parser(\"type\"); rbt.add_argument(\"text\")\n    rbt.add_argument(\"--ref\"); rbt.add_argument(\"--tab-id\", type=int)\n    rbk = rb.add_parser(\"key\"); rbk.add_argument(\"key\")\n    rbk.add_argument(\"--tab-id\", type=int)\n    rbu = rb.add_parser(\"upload\", help=\"set files on a file input by ref\")\n    rbu.add_argument(\"ref\"); rbu.add_argument(\"--file\", action=\"append\", required=True)\n    rbu.add_argument(\"--tab-id\", type=int)\n    rbrl = rb.add_parser(\"reload\", help=\"reload a tab (repairs wedged ADF state)\")\n    rbrl.add_argument(\"--tab-id\", type=int)\n    rbw = rb.add_parser(\"wait\", help=\"wait until an element by name appears\")\n    rbw.add_argument(\"name\"); rbw.add_argument(\"--role\")\n    rbw.add_argument(\"--timeout\", type=float, default=20)\n    rbw.add_argument(\"--tab-id\", type=int)\n    rbx = rb.add_parser(\"close\"); rbx.add_argument(\"--tab-id\", type=int)\n    rb.add_parser(\"reset\",\n                  help=\"forget every rb ref and cached tab; nothing in \"\n                       \"the browser moves\")\n    rbss = rb.add_parser(\"screenshot\", help=\"PNG of a tab's viewport\")\n    rbss.add_argument(\"--out\"); rbss.add_argument(\"--tab-id\", type=int)\n    rbss.add_argument(\"--with-overlay\", action=\"store_true\",\n                      help=\"keep the agent's own cursor and status bar in \"\n                           \"the shot (self-monitoring; default hides them)\")\n    rbocr = rb.add_parser(\"ocr\", help=\"read a tab's visible text by OCR \"\n                                      \"(CSS-pixel boxes)\")\n    rbocr.add_argument(\"--find\", help=\"where is this text drawn?\")\n    rbocr.add_argument(\"--nth\", type=int, default=1)\n    rbocr.add_argument(\"--lang\", help=\"an installed OCR language, e.g. \"\n                                      \"en-US or ar-SA\")\n    rbocr.add_argument(\"--tab-id\", type=int)\n    rbca = rb.add_parser(\"click-at\", help=\"real click at viewport CSS \"\n                                          \"coordinates (from `rb ocr`)\")\n    rbca.add_argument(\"x\", type=float); rbca.add_argument(\"y\", type=float)\n    rbca.add_argument(\"--dry\", action=\"store_true\",\n                      help=\"only say what is at that point\")\n    rbca.add_argument(\"--tab-id\", type=int)\n    rbact = rb.add_parser(\n        \"act\", help=\"press a ref (or --text found by OCR) and PROVE the page \"\n                    \"answered, trying every method\")\n    rbact.add_argument(\"ref\", nargs=\"?\")\n    rbact.add_argument(\"--text\", help=\"find the target by the text drawn on it\")\n    rbact.add_argument(\"--near\", metavar=\"TEXT\",\n                       help=\"press a control in the row of this drawn text \"\n                            \"(e.g. an unnamed icon); choose it with --pick\")\n    rbact.add_argument(\"--pick\", default=None,\n                       help=\"with --near: right (default), left, a number, \"\n                            \"or name:WORD (title/alt/id)\")\n    rbact.add_argument(\"--nth\", type=int, default=1)\n    rbact.add_argument(\"--method\", action=\"append\",\n                       choices=[\"cdp\", \"dom\", \"keyboard\", \"ocr\"],\n                       help=\"limit/ordering of methods (repeatable)\")\n    rbact.add_argument(\"--patience\", type=float,\n                       help=\"seconds to wait for a change per try (default 15)\")\n    rbact.add_argument(\"--irreversible\", action=\"store_true\",\n                       help=\"send ONCE; never repeat, never reload\")\n    rbact.add_argument(\"--no-reload\", action=\"store_true\")\n    rbact.add_argument(\"--accept-weak\", action=\"store_true\",\n                       help=\"accept a look-only answer (you have your own \"\n                            \"proof of the press, e.g. a wait that follows)\")\n    rbact.add_argument(\"--no-ensure\", action=\"store_true\",\n                       help=\"stop after the ladder: no recovery tactics, no \"\n                            \"background research, no screen recording\")\n    rbact.add_argument(\"--no-visual\", action=\"store_true\",\n                       help=\"skip the pixel comparison\")\n    rbact.add_argument(\"--expect-appear\", action=\"append\", default=[],\n                       metavar=\"NAME\", help=\"success = this name appears\")\n    rbact.add_argument(\"--expect-gone\", action=\"append\", default=[],\n                       metavar=\"NAME\", help=\"success = this name disappears\")\n    rbact.add_argument(\"--expect-download\", nargs=\"?\", const=\"~/Downloads\",\n                       metavar=\"DIR\",\n                       help=\"success = a new complete file in DIR (default \"\n                            \"~/Downloads): the evidence of a download, which \"\n                            \"changes no page\")\n    rbact.add_argument(\"--tab-id\", type=int)\n    rbv = rb.add_parser(\"video\", help=\"record the tab's screen and analyse \"\n                                      \"it: video, contact sheet, where it \"\n                                      \"changed, error text and position\")\n    rbv.add_argument(\"--seconds\", type=float, default=10.0)\n    rbv.add_argument(\"--title\", default=\"recording\")\n    rbv.add_argument(\"--tab-id\", type=int)\n    rbv.add_argument(\"--with-overlay\", action=\"store_true\",\n                     help=\"film the agent's own cursor and status bar too \"\n                          \"(self-monitoring; default hides them)\")\n    rban = rb.add_parser(\"analyse\", help=\"describe the interface: element \"\n                                         \"kinds, readability, methods, site \"\n                                         \"changes\")\n    rban.add_argument(\"--ocr\", action=\"store_true\",\n                      help=\"check the tree against what OCR reads (the \"\n                           \"default now; kept for old scripts)\")\n    rban.add_argument(\"--no-ocr\", action=\"store_true\",\n                      help=\"skip the OCR check of the tree\")\n    rban.add_argument(\"--tab-id\", type=int)\n    rb.add_parser(\"selfreload\", help=\"restart the extension after an update\")\n    rbloc = rb.add_parser(\"locate\", help=\"list the controls in the row of a \"\n                                         \"drawn text - unnamed icons included\")\n    rbloc.add_argument(\"--near\", required=True, metavar=\"TEXT\")\n    rbloc.add_argument(\"--pick\", help=\"right, left, a number, or name:WORD\")\n    rbloc.add_argument(\"--nth\", type=int, default=1)\n    rbloc.add_argument(\"--tab-id\", type=int)\n\n    # --- the desktop by its pixels ----------------------------------------\n    oc = sub.add_parser(\"ocr\", help=\"OCR a window (or the screen): text with \"\n                                    \"screen-pixel boxes\")\n    oc.add_argument(\"--window\"); oc.add_argument(\"--find\")\n    oc.add_argument(\"--nth\", type=int, default=1); oc.add_argument(\"--lang\")\n    ca = sub.add_parser(\"click-at\", help=\"real mouse click at screen \"\n                                         \"coordinates\")\n    ca.add_argument(\"x\", type=int); ca.add_argument(\"y\", type=int)\n    ca.add_argument(\"--window\", help=\"raise this window first (and check \"\n                                     \"the point is inside it)\")\n    ca.add_argument(\"--relative\", action=\"store_true\",\n                    help=\"x,y are relative to --window\")\n    ca.add_argument(\"--right\", action=\"store_true\")\n    ca.add_argument(\"--double\", action=\"store_true\")\n    ca.add_argument(\"--count\", type=int, choices=(1, 2, 3))\n    ca.add_argument(\"--button\", choices=(\"left\", \"right\", \"middle\"))\n    ca.add_argument(\"--modifier\", action=\"append\",\n                    help=\"a key held during the click (repeatable)\")\n    ca.add_argument(\"--from-zoom\", action=\"store_true\",\n                    help=\"x,y are pixels of the last zoom image\")\n    ca.add_argument(\"--delivery-mode\", choices=(\"background\", \"foreground\"),\n                    help=\"CUA's delivery; foreground needs the owner's interactive policy\")\n    fc = sub.add_parser(\"find-click\", help=\"OCR, find a text, click it\")\n    fc.add_argument(\"text\"); fc.add_argument(\"--window\")\n    fc.add_argument(\"--nth\", type=int, default=1); fc.add_argument(\"--lang\")\n\n    # --- site memory -------------------------------------------------------\n    st = sub.add_parser(\"site\", help=\"what the tool has learned about each \"\n                                     \"site\").add_subparsers(dest=\"sitesub\",\n                                                            required=True)\n    st.add_parser(\"list\", help=\"every site with memory\")\n    sts = st.add_parser(\"show\", help=\"one site's memory\"); sts.add_argument(\"host\")\n    stc = st.add_parser(\"check\", help=\"has this tab's interface changed?\")\n    stc.add_argument(\"--tab-id\", type=int)\n    sta = st.add_parser(\"accept\", help=\"make a changed interface the baseline\")\n    sta.add_argument(\"host\"); sta.add_argument(\"--page\"); sta.add_argument(\"--state\")\n    stf = st.add_parser(\"forget\", help=\"archive a site's memory (kept as .bak)\")\n    stf.add_argument(\"host\")\n    str_ = st.add_parser(\"recipe\", help=\"the ordered steps for a site\")\n    str_.add_argument(\"host\"); str_.add_argument(\"--name\")\n    strec = st.add_parser(\"record\", help=\"record the next steps as a recipe\")\n    strec.add_argument(\"action\", choices=[\"start\", \"stop\"])\n    strec.add_argument(\"name\", nargs=\"?\")\n    strp = st.add_parser(\"replay\", help=\"replay a recorded procedure, checking \"\n                                        \"the interface before each step\")\n    strp.add_argument(\"name\")\n    strp.add_argument(\"--host\", help=\"default: the host of the tab\")\n    strp.add_argument(\"--tab-id\", type=int)\n    strp.add_argument(\"--dry-run\", action=\"store_true\",\n                      help=\"read and plan without pressing anything\")\n    strp.add_argument(\"--allow-irreversible\", action=\"store_true\",\n                      help=\"also replay steps recorded as irreversible \"\n                           \"(approvals, submits, downloads)\")\n    strp.add_argument(\"--text\", action=\"append\", default=[],\n                      metavar=\"ROLE|NAME=VALUE\",\n                      help=\"text for a typed step whose text was not kept\")\n    stk = st.add_parser(\"know\", help=\"the site knowledge graph (kgraph 2.2): \"\n                                     \"build | ask | explain | search | lesson \"\n                                     \"| status\")\n    stk.add_argument(\"action\", choices=[\"build\", \"ask\", \"explain\", \"search\",\n                                        \"lesson\", \"status\"])\n    stk.add_argument(\"words\", nargs=\"*\")\n    stk.add_argument(\"--answer\", default=\"\")\n    stk.add_argument(\"--outcome\", choices=[\"useful\", \"dead_end\", \"corrected\"],\n                     default=\"useful\")\n    stk.add_argument(\"--node\", action=\"append\", default=[])\n    stpg = st.add_parser(\"page\", help=\"what is known about the tab's page\")\n    stpg.add_argument(\"--tab-id\", type=int)\n\n    from .contracts.research_catalog import SOURCES as _SOURCES\n    rs = sub.add_parser(\"research\", help=\"search every public knowledge base \"\n                                         \"(code, Q&A, papers, docs, the web) \"\n                                         \"for a way past a stuck control\")\n    rs.add_argument(\"query\")\n    rs.add_argument(\"--site\", help=\"keep the results in this host's memory\")\n    rs.add_argument(\"--limit\", type=int, default=5)\n    rs.add_argument(\"--source\", action=\"append\", choices=list(_SOURCES))\n\n    ap = sub.add_parser(\"approve\", help=\"approve a pending action\")\n    ap.add_argument(\"token\")\n    dn = sub.add_parser(\"deny\", help=\"deny a pending action\")\n    dn.add_argument(\"token\")\n\n    cfg = sub.add_parser(\"config\").add_subparsers(dest=\"sub\", required=True)\n    cfg.add_parser(\"get\")\n    cs = cfg.add_parser(\"set\")\n    cs.add_argument(\"key\", choices=[\"permission-mode\", \"default-browser\",\n                                    \"steal-focus\", \"desktop-interactive-fallback\"],\n                    help=\"steal-focus on|off decides whether the tool may \"\n                         \"take the screen while it works\")\n    cs.add_argument(\"value\")\n\n    mc = sub.add_parser(\n        \"mcp\", help=\"serve the Model Context Protocol over stdio so any \"\n                    \"MCP assistant can drive this machine\")\n    mc.add_argument(\"--profile\", default=\"all\",\n                    help=\"comma-separated tool groups (system, desktop, \"\n                         \"files, browser, rb) - a narrower profile costs \"\n                         \"the assistant fewer context tokens\")\n    ap_ = sub.add_parser(\n        \"api\", help=\"serve a local HTTP API for programs that do not \"\n                    \"speak MCP (loopback + bearer token)\")\n    ap_.add_argument(\"--profile\", default=\"all\")\n    ap_.add_argument(\"--port\", type=int, default=0,\n                     help=\"0 picks a free port (default)\")\n    ap_.add_argument(\"--verbose\", action=\"store_true\")\n    hi = sub.add_parser(\n        \"history\", help=\"what past sessions did - kept small, on purpose\"\n    ).add_subparsers(dest=\"histsub\", required=True)\n    hil = hi.add_parser(\"list\", help=\"recent sessions\")\n    hil.add_argument(\"--limit\", type=int, default=20)\n    his = hi.add_parser(\"show\", help=\"one session, step by step\")\n    his.add_argument(\"id\")\n    hif = hi.add_parser(\"forget\", help=\"delete one record\")\n    hif.add_argument(\"id\")\n\n    fl = sub.add_parser(\n        \"flow\", help=\"run a queue by declared criteria: the profile says \"\n                     \"what an item is and which to skip; the engine does \"\n                     \"the walking, deduping and acting\").add_subparsers(\n        dest=\"flowsub\", required=True)\n    fl.add_parser(\"list\", help=\"installed profiles\")\n    flv = fl.add_parser(\"validate\", help=\"check a profile before it runs\")\n    flv.add_argument(\"profile\")\n    fla = fl.add_parser(\n        \"analyse\", help=\"read a page and say what it IS: what repeats, \"\n                        \"what paginates, what commits. Reads only.\")\n    fla.add_argument(\"--surface\", default=\"rb\", choices=[\"rb\", \"browser\"])\n    fla.add_argument(\"--tab-id\", type=int)\n    fla.add_argument(\"--emit\", metavar=\"PATH\",\n                     help=\"write a DRAFT profile built from what was found\")\n    fla.add_argument(\"--name\", default=\"draft\")\n    flr = fl.add_parser(\"run\", help=\"work the queue in the foreground\")\n    flr.add_argument(\"profile\")\n    flr.add_argument(\"--minutes\", type=float, default=60.0)\n    flr.add_argument(\"--max-items\", type=int, default=0)\n    flr.add_argument(\"--max-acted\", type=int, default=0,\n                     metavar=\"N\",\n                     help=\"stop after N irreversible actions; the budget \"\n                          \"that matters on a live run\")\n    flr.add_argument(\"--tag\", default=\"S1\",\n                     help=\"a label for this run, written on every row\")\n    flr.add_argument(\"--dry-run\", action=\"store_true\",\n                     help=\"classify and record, never act\")\n    flr.add_argument(\"--repeat\", type=int, default=1,\n                     help=\"run the whole queue pass this many times (each finished pass is reported \"\n                          \"to the Kgrow.io dashboard); a Stop ends it before the next pass\")\n    fls = fl.add_parser(\"start\", help=\"launch a run in the background\")\n    fls.add_argument(\"profile\")\n    fls.add_argument(\"--minutes\", type=float, default=60.0)\n    fls.add_argument(\"--max-items\", type=int, default=0)\n    fls.add_argument(\"--tag\", default=\"S1\")\n    fls.add_argument(\"--dry-run\", action=\"store_true\")\n    fls.add_argument(\"--repeat\", type=int, default=1, help=\"run the queue pass this many times\")\n    flx = fl.add_parser(\n        \"stop\", help=\"ask a running flow to wind up cleanly\")\n    flx.add_argument(\"profile\")\n    flt = fl.add_parser(\"status\", help=\"the run's durable journal\")\n    flt.add_argument(\"profile\")\n    flc = fl.add_parser(\"reconcile\",\n                        help=\"rebuild the workbook from the journal\")\n    flc.add_argument(\"profile\")\n\n    sub.add_parser(\"tools\", help=\"list the MCP/API tool catalogue\")\n\n    wd = sub.add_parser(\n        \"watch\", help=\"supervise a long run: sample it passively, \"\n                      \"diagnose it, record the timeline\")\n    wd.add_argument(\"--command\",\n                    help=\"the command to supervise and, if it stalls, \"\n                         \"restart; omit to watch without supervising\")\n    wd.add_argument(\"--log\", help=\"the run's output file, watched by age\")\n    wd.add_argument(\"--journal\",\n                    help=\"a JSON-Lines record, watched by growth\")\n    wd.add_argument(\"--minutes\", type=float, default=60.0)\n    wd.add_argument(\"--interval\", type=float, default=60.0,\n                    help=\"seconds between samples (default 60)\")\n    wd.add_argument(\"--stale\", type=float, default=180.0,\n                    help=\"seconds of silence before a stall is suspected\")\n    wd.add_argument(\"--max-restarts\", type=int, default=3)\n    wd.add_argument(\"--done\", metavar=\"REGEX\",\n                    help=\"a line that means the run has ENDED (default: the \"\n                         \"flow summary, exit=N, or '== ... done')\")\n    wd.add_argument(\"--no-bridge-check\", action=\"store_true\",\n                    help=\"do not probe the browser bridge\")\n    wd.add_argument(\"--status\", action=\"store_true\",\n                    help=\"print the latest verdict and exit\")\n    wd.add_argument(\"--report\", action=\"store_true\",\n                    help=\"print the timeline summary and exit\")\n    wd.add_argument(\"--limit\", type=int, default=20)\n\n    au = sub.add_parser(\"audit\", help=\"show the local operation log\")\n    au.add_argument(\"--count\", type=int, default=30)\n\n    tr = sub.add_parser(\"trace\", help=\"analyse what happened, for debugging\")\n    tr.add_argument(\"--count\", type=int, default=2000)\n\n    return p\n\n\ndef main(argv: list[str] | None = None) -> int:\n    if sys.stdout is None or sys.stderr is None:      # started by pythonw (the Kgrow.io shortcut)\n        sys.stdout = sys.stderr = open(os.devnull, \"w\", encoding=\"utf-8\")\n    args = build_parser().parse_args(argv)\n    home = home_dir()\n    if args.cmd != \"relocate\":\n        _detect_move(home)\n\n    try:\n        if args.cmd == \"daemon\":\n            if args.sub == \"run\":\n                from contextlib import ExitStack\n                from .client import read_endpoint\n                from .daemon import Daemon\n                from .installer import install_lock\n                # tf: one daemon per home, like CUA's serve, which fails fast when a daemon already listens\n                # (serve.rs:2239-2251); the OS lock is released even if this process crashes.\n                home.mkdir(parents=True, exist_ok=True)\n                held = ExitStack()\n                try:\n                    held.enter_context(install_lock(home / \"daemon.lock\"))\n                except OSError:\n                    pid = (read_endpoint(home) or {}).get(\"pid\", \"?\")\n                    print(f\"autoskill daemon is already running for {home} (pid {pid}). \"\n                          \"Run `auto daemon stop` first.\", file=sys.stderr)\n                    return 1\n                with held:\n                    try:\n                        dm = Daemon(home)\n                    except ValueError as exc:\n                        if \"journal\" not in str(exc):\n                            raise\n                        print(f\"autoskill daemon cannot start: the event journal is damaged - {exc}. \"\n                              \"Nothing was changed: move it aside (rename it; it stays as evidence) and start the \"\n                              \"daemon again.\", file=sys.stderr)\n                        return 1\n                    print(f\"autoskill daemon {VERSION}  home={home}\")\n                    try:\n                        dm.serve_forever()\n                    except KeyboardInterrupt:\n                        dm.shutdown()\n                return 0\n            # Confirmed by waiting until the daemon stops answering, so a dropped\n            # reply is not reported as a failure.\n            from .client import stop_daemon\n            return emit({\"ok\": True, \"result\": {\"shutting_down\": True,\n                                                \"stopped\": stop_daemon(home)}}, args)\n\n        if args.cmd == \"doctor\":\n            return emit(call(Method.SYSTEM_DOCTOR.value, home=home), args,\n                        _r_doctor)\n\n        if args.cmd == \"status\":\n            return emit(call(Method.SYSTEM_STATUS.value, home=home), args,\n                        _r_status)\n\n        if args.cmd == \"session\":\n            if args.sub == \"start\":\n                params = {k: v for k, v in ((\"memory\", args.memory),\n                                            (\"new_memory\", args.new_memory)) if v}\n                params[\"client\"] = {\"name\": \"cli\", \"pid\": os.getpid()}    # db1: the dashboard names the agent\n                r = call(Method.SESSION_START.value, params, home=home)\n                return emit(r, args, lambda x: print(\n                    f\"session {x['session_id']}  \"\n                    f\"permission mode: {x['permission_mode']}  \"\n                    f\"memory: {x.get('memory_space', 'default')}\"))\n            if args.sub == \"memories\":\n                return emit(call(Method.SESSION_MEMORIES.value, home=home),\n                            args, _r_memories)\n            if args.sub == \"stop\":\n                return emit(call(Method.SESSION_STOP.value,\n                                 {\"session_id\": args.id}, home=home), args,\n                            _r_session_stop)\n            return emit(call(Method.SESSION_LIST.value,\n                             {\"limit\": args.limit,\n                              **({\"cursor\": args.cursor} if args.cursor else {})}, home=home), args)\n\n        if args.cmd == \"windows\":\n            return emit(call(Method.DESKTOP_WINDOWS.value, {\"all\": args.all},\n                             session=args.session, home=home), args, _r_windows)   # t5f F4: the agent's step\n\n        if args.cmd == \"observe\":\n            observe_params = {\"window\": args.window, \"all\": args.all,\n                              \"max_nodes\": args.max_nodes,\n                              \"max_depth\": args.max_depth}\n            if getattr(args, \"no_screenshot\", False):\n                observe_params[\"screenshot\"] = False\n            if getattr(args, \"query\", None):\n                observe_params[\"query\"] = args.query\n            return emit(call(Method.DESKTOP_OBSERVE.value, observe_params,\n                             session=args.session, home=home), args, _r_observe)\n\n        if args.cmd == \"extract\":\n            return emit(call(Method.DESKTOP_EXTRACT.value,\n                             {\"window\": args.window,\n                              \"max_chars\": args.max_chars},\n                             session=args.session, home=home), args, _r_extract)\n\n        simple: dict[str, tuple[str, dict[str, Any]]] = {\n            \"click\": (Method.DESKTOP_CLICK.value,\n                      {\"ref\": getattr(args, \"ref\", None),\n                       \"double\": getattr(args, \"double\", False),\n                       \"right\": getattr(args, \"right\", False),\n                       \"real\": getattr(args, \"real\", False),\n                       \"count\": getattr(args, \"count\", None),\n                       \"button\": getattr(args, \"button\", None),\n                       \"modifier\": getattr(args, \"modifier\", None),\n                       \"delivery_mode\": getattr(args, \"delivery_mode\", None),\n                       \"action\": getattr(args, \"action\", None)}),\n            \"type\": (Method.DESKTOP_TYPE.value,\n                     {\"text\": getattr(args, \"text\", \"\"),\n                      \"ref\": getattr(args, \"ref\", None),\n                      \"method\": getattr(args, \"method\", \"auto\"),\n                      \"window\": getattr(args, \"window\", None),\n                      # B8: absent flag -> None (never a local default; CUA\n                      # applies its own default 30).\n                      \"delay_ms\": getattr(args, \"delay_ms\", None),\n                      \"x\": getattr(args, \"x\", None), \"y\": getattr(args, \"y\", None),\n                      \"delivery_mode\": getattr(args, \"delivery_mode\", None)}),\n            \"key\": (Method.DESKTOP_KEY.value,\n                    {\"keys\": getattr(args, \"keys\", \"\"),\n                     \"ref\": getattr(args, \"ref\", None),\n                     \"window\": getattr(args, \"window\", None),\n                     \"x\": getattr(args, \"x\", None), \"y\": getattr(args, \"y\", None),\n                     \"delivery_mode\": getattr(args, \"delivery_mode\", None)}),\n            \"set-value\": (Method.DESKTOP_SET_VALUE.value,\n                          {\"ref\": getattr(args, \"ref\", None),\n                           \"value\": getattr(args, \"value\", \"\"),\n                           \"delivery_mode\": getattr(args, \"delivery_mode\", None)}),\n            \"focus\": (Method.DESKTOP_FOCUS.value,\n                      {\"ref\": getattr(args, \"ref\", None),\n                       \"window\": getattr(args, \"window\", None)}),\n            \"scroll\": (Method.DESKTOP_SCROLL.value,\n                       {\"ref\": getattr(args, \"ref\", None),\n                        \"direction\": getattr(args, \"direction\", \"down\"),\n                        \"amount\": getattr(args, \"amount\", 3),\n                        \"by\": getattr(args, \"by\", \"line\"),\n                        \"window\": getattr(args, \"window\", None),\n                        \"x\": getattr(args, \"x\", None),\n                        \"y\": getattr(args, \"y\", None),\n                        \"delivery_mode\": getattr(args, \"delivery_mode\", None)}),\n            \"drag\": (Method.DESKTOP_DRAG.value,\n                     {\"ref\": getattr(args, \"ref\", None),\n                      \"to_ref\": getattr(args, \"to_ref\", None),\n                      \"window\": getattr(args, \"window\", None),\n                      **{key: getattr(args, key)\n                         for key in (\"from_x\", \"from_y\", \"to_x\", \"to_y\")\n                         if getattr(args, key, None) is not None},\n                      **({\"button\": args.button}\n                         if getattr(args, \"button\", None) else {}),\n                      **{key: getattr(args, key)\n                         for key in (\"duration_ms\", \"steps\")\n                         if getattr(args, key, None) is not None},\n                      **({\"from_zoom\": True}\n                         if getattr(args, \"from_zoom\", False) else {}),\n                      **({\"delivery_mode\": args.delivery_mode}\n                         if getattr(args, \"delivery_mode\", None) else {})}),\n            \"set-window-frame\": (Method.DESKTOP_SET_WINDOW_FRAME.value,\n                                 {\"pid\": getattr(args, \"pid\", None),\n                                  \"window_id\": getattr(args, \"window_id\", None),\n                                  \"x\": getattr(args, \"x\", None),\n                                  \"y\": getattr(args, \"y\", None),\n                                  \"width\": getattr(args, \"width\", None),\n                                  \"height\": getattr(args, \"height\", None)}),\n            \"accessibility-tree\": (Method.DESKTOP_ACCESSIBILITY_TREE.value,\n                                   {}),\n            \"screen-size\": (Method.DESKTOP_SCREEN_SIZE.value, {}),\n            \"cursor-position\": (Method.DESKTOP_CURSOR_POSITION.value, {}),\n            \"move-cursor\": (Method.DESKTOP_MOVE_CURSOR.value,\n                            {\"x\": getattr(args, \"x\", None),\n                             \"y\": getattr(args, \"y\", None),\n                             \"scope\": getattr(args, \"scope\", \"desktop\")}),\n            \"screenshot\": (Method.DESKTOP_SCREENSHOT.value,\n                           {\"out\": getattr(args, \"out\", None),\n                            \"ref\": getattr(args, \"ref\", None),\n                            \"window\": getattr(args, \"window\", None)}),\n            \"zoom\": (Method.DESKTOP_ZOOM.value,\n                     {\"window_id\": getattr(args, \"window_id\", None),\n                      \"pid\": getattr(args, \"pid\", None),\n                      \"x1\": getattr(args, \"x1\", None),\n                      \"y1\": getattr(args, \"y1\", None),\n                      \"x2\": getattr(args, \"x2\", None),\n                      \"y2\": getattr(args, \"y2\", None),\n                      \"out\": getattr(args, \"out\", None)}),\n            \"open-app\": (Method.DESKTOP_OPEN_APP.value,\n                         {\"command\": getattr(args, \"command\", \"\"),\n                          \"args\": getattr(args, \"args\", None),\n                          \"wait_title\": getattr(args, \"wait_title\", None),\n                          \"timeout\": getattr(args, \"timeout\", 20),\n                          \"start_minimized\": getattr(args, \"start_minimized\", False),\n                          \"urls\": getattr(args, \"urls\", None)}),\n            \"wait-window\": (Method.DESKTOP_WAIT_WINDOW.value,\n                            {\"window\": getattr(args, \"window\", None),\n                             \"timeout\": getattr(args, \"timeout\", 20),\n                             \"gone\": getattr(args, \"gone\", False)}),\n            \"wait-for\": (Method.DESKTOP_WAIT_REF.value,\n                         {\"name\": getattr(args, \"name\", \"\"),\n                          \"window\": getattr(args, \"window\", None),\n                          \"timeout\": getattr(args, \"timeout\", 20)}),\n            \"close-window\": (Method.DESKTOP_CLOSE_WINDOW.value,\n                             {\"window\": getattr(args, \"window\", None)}),\n            \"quit-app\": (Method.DESKTOP_QUIT_APP.value,\n                         {\"process\": getattr(args, \"process\", \"\"),\n                          **({\"pid\": args.pid} if getattr(args, \"pid\", None) is not None else {}),\n                          \"timeout\": getattr(args, \"timeout\", 12)}),\n            \"invoke-menu\": (Method.DESKTOP_INVOKE_MENU.value,\n                            {\"window_id\": getattr(args, \"window_id\", None),\n                             \"pid\": getattr(args, \"pid\", None),\n                             \"path\": getattr(args, \"path\", [])}),\n            # B19: only the flags the caller actually passed are sent (the\n            # map drops argparse's implicit Nones), so {} reaches the driver\n            # for a bare clipboard-write - the driver owns exactly-one (R10).\n            \"clipboard-read\": (Method.DESKTOP_CLIPBOARD_READ.value,\n                               {**({\"include_text\": True}\n                                   if getattr(args, \"include_text\", False) else {})}),\n            \"clipboard-write\": (Method.DESKTOP_CLIPBOARD_WRITE.value,\n                                {key: getattr(args, key)\n                                 for key in (\"text\", \"image_path\", \"file_path\")\n                                 if getattr(args, key, None) is not None}),\n            # B20: the map JSON-decodes each --expect flag into one\n            # predicate object and forwards only the flags actually given -\n            # CUA's own defaults apply when the optionals are absent.\n            \"verify-state\": (Method.DESKTOP_VERIFY_STATE.value,\n                             {\"pid\": getattr(args, \"pid\", None),\n                              \"window_id\": getattr(args, \"window_id\", None),\n                              \"expect\": [json.loads(item) for item\n                                         in getattr(args, \"expect\", []) or []],\n                              **{key: getattr(args, key)\n                                 for key in (\"timeout_ms\", \"stable_samples\")\n                                 if getattr(args, key, None) is not None},\n                              **({\"include_screenshot\": True}\n                                 if getattr(args, \"include_screenshot\", False)\n                                 else {})}),\n            \"copy\": (Method.DESKTOP_COPY.value,\n                     {\"sources\": (getattr(args, \"paths\", []) or [])[:-1],\n                      \"destination\": (getattr(args, \"paths\", []) or [\"\"])[-1]}),\n            \"report\": (Method.DESKTOP_REPORT.value,\n                       {\"file\": getattr(args, \"file\", \"\"),\n                        \"title\": getattr(args, \"title\", None),\n                        \"blocks\": getattr(args, \"block\", [])}),\n            \"apps\": (Method.DESKTOP_APPS.value,\n                     {\"find\": getattr(args, \"find\", None),\n                      \"class\": getattr(args, \"klass\", None)}),\n            \"table\": ((Method.DESKTOP_TABLE_EXPORT.value,          # fix-r3 T13: auto table FILE --export DEST\n                       {\"file\": getattr(args, \"file\", \"\"), \"destination\": getattr(args, \"export\", \"\")})\n                      if getattr(args, \"export\", None) else\n                      ((Method.DESKTOP_TABLE_READ.value\n                        if getattr(args, \"show\", False)\n                        else Method.DESKTOP_TABLE_APPEND.value),\n                       {\"file\": getattr(args, \"file\", \"\"),\n                        \"header\": getattr(args, \"header\", None),\n                        \"rows\": getattr(args, \"row\", []),\n                        \"sep\": getattr(args, \"sep\", \"\\t\"),\n                        \"dedup\": getattr(args, \"dedup\", None),\n                        \"limit\": getattr(args, \"limit\", 50)})),\n            \"request-help\": (Method.HUMAN_REQUEST_HELP.value,\n                             {\"prompt\": getattr(args, \"prompt\", \"\"),\n                              \"timeout\": getattr(args, \"timeout\", 180)}),\n            \"click-at\": (Method.DESKTOP_CLICK_AT.value,\n                         {\"x\": getattr(args, \"x\", 0), \"y\": getattr(args, \"y\", 0),\n                          \"window\": getattr(args, \"window\", None),\n                          \"relative\": getattr(args, \"relative\", False),\n                          \"right\": getattr(args, \"right\", False),\n                          \"double\": getattr(args, \"double\", False),\n                          \"from_zoom\": getattr(args, \"from_zoom\", False),\n                          \"count\": getattr(args, \"count\", None),\n                          \"button\": getattr(args, \"button\", None),\n                          \"modifier\": getattr(args, \"modifier\", None),\n                          \"delivery_mode\": getattr(args, \"delivery_mode\", None)}),\n            \"find-click\": (Method.DESKTOP_FIND_CLICK.value,\n                           {\"text\": getattr(args, \"text\", \"\"),\n                            \"window\": getattr(args, \"window\", None),\n                            \"nth\": getattr(args, \"nth\", 1),\n                            \"lang\": getattr(args, \"lang\", None)}),\n        }\n        if args.cmd == \"setup\":\n            from . import setup as _setup\n            rep = _setup.run_checks(fix=getattr(args, \"fix\", False))\n            print(_setup.render_report(rep))\n            return 0 if rep[\"all_ok\"] else 1\n\n        if args.cmd in simple:\n            method, params = simple[args.cmd]\n            return emit(call(method, params, session=args.session, home=home),\n                        args, _r_action)\n\n        if args.cmd == \"browser\":\n            if args.sub == \"tab\":\n                tmap = {\n                    \"new\": (Method.BROWSER_TAB_NEW.value,\n                            {\"url\": getattr(args, \"url\", None)}),\n                    \"list\": (Method.BROWSER_TAB_LIST.value, {}),\n                    \"select\": (Method.BROWSER_TAB_SELECT.value,\n                               {\"tab_id\": getattr(args, \"tab_id\", None)}),\n                    \"close\": (Method.BROWSER_TAB_CLOSE.value,\n                              {\"tab_id\": getattr(args, \"tab_id\", None)}),\n                }\n                method, params = tmap[args.tabsub]\n                return emit(call(method, params, session=args.session,\n                                 home=home), args,\n                            _r_action if args.tabsub != \"list\" else _r_tabs)\n            bmap = {\n                \"open\": (Method.BROWSER_OPEN.value,\n                         {\"url\": getattr(args, \"url\", None),\n                          \"headless\": getattr(args, \"headless\", False),\n                          \"browser\": getattr(args, \"browser\", None)}),\n                \"navigate\": (Method.BROWSER_NAVIGATE.value,\n                             {\"url\": getattr(args, \"url\", \"\")}),\n                \"observe\": (Method.BROWSER_OBSERVE.value,\n                            {\"max_nodes\": getattr(args, \"max_nodes\", 2500),\n                             \"max_tokens\": getattr(args, \"max_tokens\", None)}),\n                \"more\": (Method.BROWSER_OBSERVE_MORE.value,\n                         {\"cursor\": getattr(args, \"cursor\", None),\n                          \"max_tokens\": getattr(args, \"max_tokens\", 3000)}),\n                \"click\": (Method.BROWSER_CLICK.value,\n                          {\"ref\": getattr(args, \"ref\", None),\n                           \"clicks\": getattr(args, \"clicks\", 1)}),\n                \"type\": (Method.BROWSER_TYPE.value,\n                         {\"text\": getattr(args, \"text\", \"\"),\n                          \"ref\": getattr(args, \"ref\", None),\n                          \"clear\": getattr(args, \"clear\", False)}),\n                \"key\": (Method.BROWSER_KEY.value, {\"key\": getattr(args, \"key\", \"\")}),\n                \"scroll\": (Method.BROWSER_SCROLL.value,\n                           {\"delta_y\": getattr(args, \"delta_y\", None),\n                            \"delta_x\": getattr(args, \"delta_x\", None)}),\n                \"screenshot\": (Method.BROWSER_SCREENSHOT.value,\n                               {\"out\": getattr(args, \"out\", None),\n                                \"full_page\": getattr(args, \"full_page\", False),\n                                \"lazy\": getattr(args, \"lazy\", False)}),\n                \"close\": (Method.BROWSER_CLOSE.value, {}),\n                \"select\": (Method.BROWSER_SELECT.value,\n                           {\"ref\": getattr(args, \"ref\", None),\n                            \"value\": getattr(args, \"value\", None),\n                            \"label\": getattr(args, \"label\", None)}),\n                \"back\": (Method.BROWSER_BACK.value,\n                         {\"delta\": getattr(args, \"delta\", -1)}),\n                \"reload\": (Method.BROWSER_RELOAD.value, {}),\n                \"hover\": (Method.BROWSER_HOVER.value,\n                          {\"ref\": getattr(args, \"ref\", None)}),\n                \"get-html\": (Method.BROWSER_GET_HTML.value,\n                             {\"ref\": getattr(args, \"ref\", None),\n                              \"max_chars\": getattr(args, \"max_chars\", 200000)}),\n                \"extract\": (Method.BROWSER_EXTRACT.value,\n                            {\"kind\": getattr(args, \"kind\", \"text\"),\n                             \"ref\": getattr(args, \"ref\", None),\n                             \"max_chars\": getattr(args, \"max_chars\", 20000)}),\n                \"popups\": (Method.BROWSER_POPUPS.value,\n                           {\"clear\": getattr(args, \"clear\", False)}),\n                \"list\": (Method.BROWSER_LIST.value, {}),\n                \"console\": (Method.BROWSER_CONSOLE.value,\n                            {\"limit\": getattr(args, \"limit\", 50)}),\n                \"dialog\": (Method.BROWSER_DIALOG_POLICY.value,\n                           {\"policy\": getattr(args, \"policy\", \"dismiss\")}),\n                \"wait\": (Method.BROWSER_WAIT.value,\n                         {\"text\": getattr(args, \"text\", None),\n                          \"timeout\": getattr(args, \"timeout\", 20)}),\n            }\n            method, params = bmap[args.sub]\n            params[\"tab_id\"] = getattr(args, \"tab_id\", None)\n            if args.sub == \"open\":\n                params.pop(\"tab_id\")     # opening has no existing tab to pick\n            renderer = _r_observe if args.sub in (\"observe\", \"more\") else _r_action\n            return emit(call(method, params, session=args.session, home=home),\n                        args, renderer)\n\n        if args.cmd in (\"approve\", \"deny\"):\n            return _answer(home, args)\n\n        if args.cmd == \"config\":\n            if args.sub == \"get\":\n                return emit(call(Method.CONFIG_GET.value, home=home), args)\n            # Deliberately NOT an RPC. The permission mode is the user's\n            # control over the agent; routing it through the daemon would make\n            # it something the agent can ask for, and a safety switch the\n            # agent can request is not a safety switch. The CLI writes the\n            # policy file directly and the daemon picks it up on its next\n            # request, so this path exists only for whoever has the shell.\n            return _set_mode_locally(home, args)\n\n        if args.cmd == \"trace\":\n            return emit(call(Method.AUDIT_TRACE.value, {\"count\": args.count},\n                             session=args.session, home=home), args, _r_trace)\n\n        if args.cmd == \"audit\":\n            return emit(call(Method.AUDIT_TAIL.value, {\"count\": args.count},\n                             session=args.session, home=home), args,\n                        _r_audit)\n\n        if args.cmd == \"history\":\n            if args.histsub == \"list\":\n                return emit(call(Method.HISTORY_LIST.value,\n                                 {\"limit\": args.limit}, home=home),\n                            args, _r_history_list)\n            if args.histsub == \"show\":\n                return emit(call(Method.HISTORY_SHOW.value,\n                                 {\"id\": args.id}, home=home), args,\n                            _r_history_show)\n            return emit(call(Method.HISTORY_FORGET.value,\n                             {\"id\": args.id}, home=home), args, _r_action)\n\n        if args.cmd == \"flow\":\n            if args.flowsub == \"list\":\n                return emit(call(Method.FLOW_LIST.value, home=home),\n                            args, _r_flow_list)\n            if args.flowsub == \"validate\":\n                return emit(call(Method.FLOW_VALIDATE.value,\n                                 {\"profile\": args.profile}, home=home),\n                            args, _r_flow_profile)\n            if args.flowsub == \"analyse\":\n                return emit(call(Method.FLOW_ANALYSE.value, {\n                    \"surface\": args.surface, \"tab_id\": args.tab_id,\n                    \"emit\": args.emit, \"name\": args.name},\n                    session=args.session, home=home, timeout=400), args, _r_flow_analyse)\n            if args.flowsub == \"stop\":\n                # A file, not a signal, because `flow start` puts the run in\n                # another process. The runner checks it between items and\n                # before any irreversible step, so the item in flight\n                # finishes rather than being cut in half.\n                from .workflow import stop_file_for\n                sp = stop_file_for(home, args.profile)\n                sp.write_text(\"asked to stop from the command line\",\n                              encoding=\"utf-8\")\n                print(f\"stop requested for {args.profile!r}\")\n                print(\"  the run finishes the item it is on, then returns;\")\n                print(\"  nothing new is opened and nothing is left half-done\")\n                return 0\n            if args.flowsub == \"status\":\n                return emit(call(Method.FLOW_STATUS.value,\n                                 {\"profile\": args.profile}, home=home),\n                            args, _r_flow_status)\n            if args.flowsub == \"reconcile\":\n                return emit(call(Method.FLOW_RECONCILE.value,\n                                 {\"profile\": args.profile}, home=home),\n                            args, _r_flow_reconcile)\n            if args.flowsub == \"start\":\n                return emit(call(Method.FLOW_START.value, {\n                    \"profile\": args.profile, \"minutes\": args.minutes,\n                    \"max_items\": args.max_items, \"tag\": args.tag,\n                    \"dry_run\": args.dry_run, \"repeat\": args.repeat}, home=home), args, _r_action)\n            # `run` stays in this process: an hours-long loop held open\n            # on an RPC would pin a daemon thread for the whole run.\n            from .workflow import FlowRunner, Profile, profiles_dir\n            name = Path(args.profile)\n            if not name.suffix and not name.exists():\n                name = profiles_dir() / f\"{args.profile}.json\"\n            try:\n                profile = Profile.load(name)\n            except ValueError as exc:\n                # A malformed profile (bad JSON, unknown step or surface)\n                # is a message for the author, not a traceback (F-25).\n                print(f\"error: profile {str(name)!r} cannot be read: {exc}\",\n                      file=sys.stderr)\n                print(f\"hint: `auto flow validate {args.profile}` explains \"\n                      f\"what is wrong.\", file=sys.stderr)\n                return 1\n            return _flow_passes(args, profile, home)\n\n        if args.cmd == \"watch\":\n            if args.status:\n                return emit(call(Method.SYSTEM_WATCH_STATUS.value,\n                                 home=home), args, _r_watch_status)\n            if args.report:\n                return emit(call(Method.SYSTEM_WATCH_TIMELINE.value,\n                                 {\"limit\": args.limit}, home=home),\n                            args, _r_watch_report)\n            from .watchdog import Watchdog\n            # t5f F1: the bridge is pinged directly, as the daemon's own watchdog does (handlers.py), never through\n            # an rb.status request - that request became a step of the owner's run and an audit error.\n            probe = {}\n            if not args.no_bridge_check:\n                from .orchestrator.monitoring import NativeBridgeHealth\n                probe[\"bridge_health\"] = NativeBridgeHealth()\n            wd = Watchdog(\n                home,\n                log=Path(args.log) if args.log else None,\n                journal=Path(args.journal) if args.journal else None,\n                command=args.command,\n                interval_s=args.interval, stale_s=args.stale,\n                max_restarts=args.max_restarts,\n                check_bridge=not args.no_bridge_check,\n                **probe,\n                **({\"done_pattern\": args.done} if args.done else {}))\n            return wd.run(args.minutes)\n\n        if args.cmd == \"mcp\":\n            from .mcp_server import main as _mcp\n            return _mcp(profile=args.profile, home=home)\n\n        if args.cmd == \"api\":\n            from .api import serve as _api\n            return _api(profile=args.profile, port=args.port, home=home,\n                        verbose=args.verbose)\n\n        if args.cmd == \"tools\":\n            from . import toolspec\n            rows = toolspec.select(\"all\")\n            if args.json:\n                print(json.dumps(\n                    [{\"name\": t[\"name\"], \"group\": t[\"group\"],\n                      \"method\": t[\"method\"],\n                      \"description\": t[\"description\"],\n                      \"inputSchema\": t[\"schema\"]} for t in rows],\n                    ensure_ascii=False, indent=2))\n                return 0\n            group = None\n            for t in rows:\n                if t[\"group\"] != group:\n                    group = t[\"group\"]\n                    print(\"\\n[\" + group + \"]\")\n                print(f\"  {t['name']:<20} {t['description'][:78]}\")\n            print(f\"\\n{len(rows)} tools. `auto mcp` serves them \"\n                  f\"over MCP; `auto api` over HTTP.\")\n            return 0\n\n        if args.cmd == \"rb\":\n            return _rb_command(args, home)\n\n        if args.cmd == \"ocr\":\n            return emit(call(Method.DESKTOP_OCR.value,\n                             {\"window\": args.window, \"find\": args.find,\n                              \"nth\": args.nth, \"lang\": args.lang},\n                             session=args.session, home=home, timeout=240),\n                        args, _r_ocr)\n\n        if args.cmd == \"site\":\n            return _site_command(args, home)\n\n        if args.cmd == \"app\":\n            return _app_command(args, home)\n\n        if args.cmd == \"mind\":\n            return _mind_command(args, home)\n\n        if args.cmd == \"path\":\n            if args.pathsub == \"list\":\n                return emit(call(Method.PATH_LIST.value, session=args.session, home=home), args, _r_paths)\n            if args.pathsub == \"show\":\n                return emit(call(Method.PATH_SHOW.value, {\"name\": args.name, \"site\": args.site},\n                                 session=args.session, home=home), args, _r_path_show)\n            return emit(call(Method.PATH_RUN.value,\n                             {\"name\": args.name, \"site\": args.site, \"dry_run\": args.dry_run,\n                              \"allow_irreversible\": args.allow_irreversible, \"max_items\": args.max_items,\n                              \"tab_id\": args.tab_id, \"texts\": args.text, \"repeat\": args.repeat},\n                             session=args.session, home=home, timeout=3600), args)\n\n        if args.cmd == \"relocate\":\n            return _relocate_command(args, home)\n\n        if args.cmd == \"dashboard\":\n            return _dashboard_command(args, home)\n\n        if args.cmd == \"run\":\n            params = ({\"count\": args.count} if args.runsub == \"repeat\"\n                      else {\"name\": args.name} if args.runsub == \"save\" else {})\n            return emit(call(f\"_run.{args.runsub}\", params, home=home, start_if_missing=False,\n                             timeout=120), args, _r_run)\n\n        if args.cmd == \"research\":\n            return emit(call(Method.RESEARCH_SEARCH.value,\n                             {\"query\": args.query, \"site\": args.site,\n                              \"limit\": args.limit,\n                              \"sources\": args.source or None},\n                             session=args.session, home=home, timeout=300), args, _r_research)\n\n    except DaemonUnavailable as exc:\n        print(f\"error: {exc}\", file=sys.stderr)\n        return 2\n    except ProtocolError as exc:\n        # Work that runs in this process (`flow run`, `watch`, ...) raises the\n        # same errors the daemon would send back; they get the same shape\n        # `emit` gives a daemon error, not a traceback. Measured: a profile\n        # the validator refused came out as a raw stack trace (F-25).\n        print(f\"error: {exc.error.message}\", file=sys.stderr)\n        if exc.error.hint:\n            print(f\"hint: {exc.error.hint}\", file=sys.stderr)\n        return 1\n    except (ConnectionError, socket.timeout) as exc:\n        print(f\"error: cannot reach the daemon: {exc}\", file=sys.stderr)\n        print(\"hint: try `auto status`, or `auto daemon run` to see errors.\",\n              file=sys.stderr)\n        return 2\n    return 0\n\n\ndef _r_session_stop(r: dict[str, Any]) -> None:\n    print(f\"stopped {r.get('stopped')}  (working state cleared)\")\n    error = r.get(\"cua_error\") or {}\n    if error:\n        print(f\"  CUA cleanup: {error.get('code', 'driver_error')}: \"\n              f\"{error.get('message', 'missing error')}\")\n    elif r.get(\"cua_session\") == \"unavailable\":\n        print(\"  CUA session: unavailable\")\n    if r.get(\"history\"):\n        from pathlib import Path as _P\n        rec = _P(r[\"history\"])\n        size = rec.stat().st_size if rec.exists() else 0\n        print(f\"  kept a {size} byte record of what was done: \"\n              f\"`auto history show {rec.stem}`\")\n\n\ndef _r_paths(r: dict[str, Any]) -> None:\n    rows = r.get(\"paths\") or []\n    for row in rows:\n        where = row.get(\"site\") or \"\"\n        size = f\"{row['steps']} steps\" if row.get(\"kind\") == \"recipe\" else (row.get(\"description\") or \"\")[:60]\n        print(f\"  {row['name']:<28} {row['kind']:<8} {where:<28} {size}\")\n    print(\"\\nno saved paths yet: record one with `auto site record start NAME` ... `stop`\" if not rows\n          else \"\\nrun one by its exact name: #path NAME  (auto path run NAME)\")\n\n\ndef _r_path_show(r: dict[str, Any]) -> None:\n    print(f\"{r['name']}  ({r['kind']} on {r.get('site') or 'any site'})\")\n    steps = (r.get(\"turns\") if r.get(\"kind\") == \"run\" else r.get(\"steps\")) or []\n    for i, step in enumerate(steps, 1):\n        if r.get(\"kind\") == \"run\":\n            target = step.get(\"target\") or {}\n            identity = target.get(\"ref\") or target.get(\"window\") or {}\n            label = identity.get(\"name\") or identity.get(\"window_title\") or \"\"\n            print(f\"  {i:>2}. {step.get('tool', '')} {label}\".rstrip())\n            continue\n        mark = \"  [irreversible]\" if step.get(\"irreversible\") else \"\"\n        print(f\"  {i:>2}. {step.get('verb', '')} {step.get('target') or step.get('name') or ''} \"\n              f\"{('= ' + str(step['text'])) if step.get('text') else ''}{mark}\".rstrip())\n    if r.get(\"summary\"):\n        print(json.dumps(r[\"summary\"], ensure_ascii=False, indent=2))\n\n\ndef _r_memories(r: dict[str, Any]) -> None:\n    for row in r.get(\"spaces\") or []:\n        print(f\"{row['name']:<24} sites {row['sites']:<4} apps {row['apps']:<4} {row['path']}\")\n    print(\"\\nload one with `auto session start --memory NAME`; \"\n          \"start a new one with `auto session start --new-memory NAME`\")\n\n\ndef _r_history_list(r: dict[str, Any]) -> None:\n    rows = r.get(\"records\") or []\n    for x in rows:\n        flag = f\"  {x['failed']} failed\" if x.get(\"failed\") else \"\"\n        print(f\"  {x['id']}  {str(x.get('title'))[:56]:<58} \"\n              f\"{x.get('operations')} ops{flag}\")\n    kb = (r.get(\"total_bytes\") or 0) / 1024\n    print(f\"\\n{len(rows)} record(s), {kb:.1f} KB total in {r.get('dir')}\")\n    if rows:\n        print(\"  `auto history show <id>` replays what was done, in order.\")\n\n\ndef _r_history_show(r: dict[str, Any]) -> None:\n    print(f\"{r.get('id')}  {r.get('title')}\")\n    print(f\"  {r.get('started')} -> {r.get('ended')}   \"\n          f\"{r.get('operations')} operations, {r.get('failed')} failed\")\n    print(\"\\n  steps:\")\n    for i, s in enumerate(r.get(\"steps\") or [], 1):\n        print(f\"    {i:>3}. {s}\")\n    if r.get(\"artifacts\"):\n        print(\"\\n  produced:\")\n        for a in r[\"artifacts\"]:\n            print(f\"    {a}\")\n    if r.get(\"errors\"):\n        print(\"\\n  failures:\")\n        for e in r[\"errors\"]:\n            print(f\"    {e.get('verb')}: {e.get('error')}\")\n\n\ndef _r_flow_list(r: dict[str, Any]) -> None:\n    rows = r.get(\"profiles\") or []\n    for p in rows:\n        if p.get(\"error\"):\n            print(f\"  [BAD ] {p['name']}: {p['error'][:90]}\")\n            continue\n        print(f\"  [{p.get('surface', '?'):<7}] {p['name']}\")\n        if p.get(\"description\"):\n            print(f\"            {p['description'][:92]}\")\n        print(f\"            gates: {', '.join(p.get('gates') or [])}\"\n              f\"   steps: {' -> '.join(p.get('steps') or [])}\")\n    print(f\"\\n{len(rows)} profile(s). `auto flow validate <name>` before \"\n          f\"a run; `--dry-run` before trusting it.\")\n\n\ndef _r_flow_profile(r: dict[str, Any]) -> None:\n    print(f\"{r.get('name')}  [{r.get('surface')}]  valid\")\n    if r.get(\"description\"):\n        print(f\"  {r['description']}\")\n    print(f\"  gates: {', '.join(r.get('gates') or [])}\")\n    if r.get(\"reach\"):\n        print(f\"  reach: {' -> '.join(r['reach'])}   \"\n              f\"(run when the list is not showing)\")\n    print(f\"  steps: {' -> '.join(r.get('steps') or [])}   \"\n          f\"(* = the irreversible one)\")\n    if r.get(\"ledger\"):\n        print(f\"  ledger: {r['ledger']}\")\n\n\ndef _r_flow_analyse(r: dict[str, Any]) -> None:\n    from .analyse import render\n    print(render(r))\n    if r.get(\"emitted\"):\n        print(f\"\\n  draft profile -> {r['emitted']}\")\n        print(f\"  {r.get('note', '')}\")\n\n\ndef _r_flow_reconcile(r: dict[str, Any]) -> None:\n    total = r.get(\"journal_rows\", 0)\n    written = r.get(\"written\", 0)\n    already = r.get(\"already_present\", 0)\n    print(f\"{total} journal row(s) replayed: {written} written, \"\n          f\"{already} already present\")\n    if total and not written:\n        print(\"  nothing to do - the workbook already matches the journal\")\n\n\ndef _r_flow_status(r: dict[str, Any]) -> None:\n    print(f\"{r.get('profile')}: {r.get('rows')} journal row(s), \"\n          f\"{r.get('decided')} item(s) decided\")\n    acts = r.get(\"actions\") or {}\n    if acts:\n        print(\"  \" + \"  \".join(f\"{k}={v}\" for k, v in sorted(acts.items())))\n    unconfirmed = r.get(\"unconfirmed\") or []\n    if unconfirmed:\n        print(f\"  {len(unconfirmed)} DISPATCHED WITHOUT CONFIRMATION - \"\n              f\"check these by hand:\")\n        for u in unconfirmed[:10]:\n            print(f\"    {u}\")\n    print(f\"  journal: {r.get('journal')}\")\n\n\ndef _r_watch_status(r: dict[str, Any]) -> None:\n    print(f\"{r.get('verdict', '?')}  {r.get('reason', '')}\")\n    bits = [f\"{k}={r[k]}\" for k in\n            (\"at\", \"age_s\", \"log_age_s\", \"journal_rows\", \"journal_delta\",\n             \"audit_ops\", \"audit_errors\", \"error_rate\", \"bridge\",\n             \"restarts\", \"supervising\") if r.get(k) is not None]\n    if bits:\n        print(\"  \" + \"  \".join(str(b) for b in bits))\n\n\ndef _r_watch_report(r: dict[str, Any]) -> None:\n    print(f\"{r.get('samples', 0)} sample(s): \"\n          + \", \".join(f\"{k} {v}\" for k, v in\n                      sorted((r.get(\"verdicts\") or {}).items())))\n    problems = r.get(\"problems\") or []\n    if not problems:\n        print(\"  no problems recorded\")\n        return\n    print(f\"  {len(problems)} problem sample(s):\")\n    for p in problems:\n        print(f\"    [{p.get('at', '')[11:]}] {p.get('verdict')}: \"\n              f\"{p.get('reason', '')}\")\n\n\ndef _r_doctor(r: dict[str, Any]) -> None:\n    for c in r.get(\"checks\", []):\n        mark = \"ok  \" if c[\"ok\"] else \"FAIL\"\n        print(f\"  [{mark}] {c['check']:<26} {c['detail']}\")\n        if c.get(\"hint\"):\n            print(f\"         hint: {c['hint']}\")\n    print()\n    print(\"all checks passed\" if r.get(\"ok\")\n          else f\"failed: {', '.join(r.get('failed', []))}\")\n\n\ndef _r_trace(r: dict[str, Any]) -> None:\n    print(f\"{r.get('entries', 0)} operations\")\n    print(\"  outcomes      :\", r.get(\"outcomes\"))\n    print(\"  effect states :\", r.get(\"effect_states\"))\n    print(\"  verbs         :\", r.get(\"verbs\"))\n    if r.get(\"unverified_actions\"):\n        print(f\"  unverified    : {r['unverified_actions']} action(s) could not \"\n              \"be confirmed\")\n    tr = r.get(\"transitions\") or []\n    if tr:\n        print(\"  common sequences:\")\n        for t in tr:\n            print(f\"    {t['n']:4d}  {t['from']} -> {t['to']}\")\n    sl = r.get(\"slowest_ms\") or []\n    if sl:\n        print(\"  slowest:\", \", \".join(f\"{x['method']} {x['ms']}ms\" for x in sl))\n    f = r.get(\"failures\") or []\n    if f:\n        print(f\"\\n  {len(f)} recent failure(s):\")\n        for x in f:\n            print(f\"    [{x.get('effect_state')}] {x.get('method')}: \"\n                  f\"{x.get('error')}\")\n    else:\n        print(\"\\n  no failures recorded\")\n\n\ndef _r_audit(r: dict[str, Any]) -> None:\n    rows = r.get(\"entries\", [])\n    if not rows:\n        print(\"no audit entries\")\n        return\n    for e in rows:\n        mark = \"!\" if e.get(\"outcome\") != \"ok\" else \" \"\n        conf = \"*\" if e.get(\"confirmed_by_user\") else \" \"\n        print(f\"{mark}{conf} {e['ts'][11:23]}  {e['method']:<22} \"\n              f\"{e.get('effect_state','?'):<9} {e.get('target') or ''}\")\n    print(\"\\n  ! = error    * = user-approved\")\n\n\ndef _r_rb_tabs(r: dict[str, Any]) -> None:\n    tabs = r.get(\"tabs\") or []\n    for t in tabs:\n        mark = \"*\" if t.get(\"active\") else \" \"\n        print(f\"{mark} {t['tabId']:<10} \"\n              f\"{(t.get('title') or '')[:52]:<54} \"\n              f\"{(t.get('url') or '')}\")\n    print(f\"\\n{len(tabs)} tab(s)   * = active\")\n\n\ndef _r_rb_observe(r: dict[str, Any]) -> None:\n    print(r.get(\"text\", \"\"))\n    if r.get(\"mode\") == \"ocr\":\n        print(f\"\\n[read by OCR: {len(r.get('lines') or [])} lines on tab \"\n              f\"{r.get('tab_id')} - the accessibility tree was not available]\")\n        return\n    print(f\"\\n[{r.get('ref_count')} refs from {r.get('node_count')} nodes \"\n          f\"on tab {r.get('tab_id')}]\")\n\n\ndef _r_rb_status(r: dict[str, Any]) -> None:\n    print(f\"bridge connected; extension {r.get('extension')} \"\n          f\"v{r.get('version', '?')}\")\n    if r.get(\"note\"):\n        print(f\"note: {r['note']}\")\n\n\ndef _r_ocr(r: dict[str, Any]) -> None:\n    for m in r.get(\"matches\") or []:\n        print(f\"match {m['text']!r} at {m['at']} box {m['box']} \"\n              f\"({m['how']}, {m['score']})\")\n    if r.get(\"matches\") is not None and not r.get(\"matches\"):\n        print(\"no match for the text asked for\")\n    for ln in (r.get(\"lines\") or [])[:200]:\n        b = ln[\"box\"]\n        print(f\"  [{b[0]:.0f},{b[1]:.0f} {b[2]:.0f}x{b[3]:.0f}] {ln['text']}\")\n    print(f\"{r.get('count', 0)} line(s)  lang={r.get('lang')}  \"\n          f\"image={r.get('image')}\")\n\n\ndef _r_click_at(r: dict[str, Any]) -> None:\n    h = r.get(\"hit\") or {}\n    print(f\"ok  effect={r.get('effect_state')}  at={r.get('at')}  \"\n          f\"hit={h.get('tag')}{'#' + h['id'] if h.get('id') else ''} \"\n          f\"{h.get('text', '')!r}\")\n\n\ndef _r_act(r: dict[str, Any]) -> None:\n    print(f\"ok  verified={r.get('verified')}  method={r.get('method')}  \"\n          f\"evidence={r.get('evidence', '?')}  after={r.get('waited_s')}s  \"\n          f\"changed={', '.join(r.get('changes') or [])}  target={r.get('target')}\")\n    if r.get(\"evidence\") == \"weak\":\n        print(\"warning: only the target's look changed (hover/pressed style?) - \"\n              \"check the page before counting this as done\")\n    for a in r.get(\"attempts\") or []:\n        print(f\"  {a.get('method')}#{a.get('try', 1)}: {a.get('outcome')}\"\n              f\" ({a.get('waited_s', 0)}s) {', '.join(a.get('changes') or [])}\")\n    for f in r.get(\"downloaded\") or []:\n        print(f\"downloaded: {f}\")\n    for m in r.get(\"memory_used\") or []:\n        print(f\"memory used: {m}\")\n    rec = r.get(\"recovery\") or {}\n    if rec:\n        print(f\"recovered by: {rec.get('recovered_by')}  (tried: \"\n              + \", \".join(t[\"tactic\"] for t in rec.get(\"tactics\") or [] if \"ok\" in t)\n              + \")\")\n        if (rec.get(\"video\") or {}).get(\"verdict\"):\n            print(f\"  recording: {rec['video']['verdict']}  ({rec['video'].get('analysis')})\")\n    if r.get(\"next\"):\n        print(f\"next: {r['next']}\")\n\n\ndef _r_locate(r: dict[str, Any]) -> None:\n    print(f\"row of {r.get('near')!r} (anchor {r.get('anchor')}): \"\n          f\"{r.get('count', 0)} control(s), left to right\")\n    for c in r.get(\"controls\") or []:\n        flag = \"\" if c.get(\"reachable\", True) else \"  [covered]\"\n        print(f\"  {c['index']}. {c['label']!r}  <{c.get('tag')}> at \"\n              f\"({c['cx']:.0f},{c['cy']:.0f}){flag}\")\n    if r.get(\"picked\"):\n        print(f\"picked: {r['picked']['index']}. {r['picked']['label']!r}\")\n    elif \"picked\" in r:\n        print(\"picked: nothing matched\")\n    if r.get(\"note\"):\n        print(f\"note: {r['note']}\")\n\n\ndef _r_interface(r: dict[str, Any]) -> None:\n    i = r.get(\"interface\") or {}\n    print(f\"readability: {i.get('readability')}  \"\n          f\"(named {i.get('named_share', 0):.0%}, frames {i.get('frames', 0)})\")\n    print(\"elements: \" + \", \".join(f\"{k} {v}\" for k, v in\n                                   (i.get(\"counts\") or {}).items()))\n    if i.get(\"ocr\"):\n        o = i[\"ocr\"]\n        print(f\"OCR check: {o.get('in_tree')}/{o.get('ocr_words')} drawn words \"\n              f\"are in the tree ({o.get('coverage')})\")\n    for m in i.get(\"recommended\") or []:\n        print(f\"drive it by: {m}\")\n    site = r.get(\"site\") or {}\n    if site:\n        prov = (f\"  [origin {site['origin']}, confidence \"\n                f\"{site.get('confidence')}\"\n                + (\", STALE\" if site.get(\"stale\") else \"\") + \"]\"\n                if site.get(\"origin\") else \"\")\n        print(f\"site memory: {site.get('status')} {site.get('host')}\"\n              f\"{site.get('page')} (similarity {site.get('similarity')})\"\n              + prov)\n        for k in (\"breaking\", \"removed\", \"added\"):\n            if site.get(k):\n                print(f\"  {k}: {', '.join(site[k][:8])}\")\n    for n in (i.get(\"notes\") or []) + (r.get(\"notes\") or []):\n        print(f\"! {n}\")\n    for kind in (\"clickable\", \"editable\", \"toggle\", \"readonly\", \"disabled\",\n                 \"protected\"):\n        items = (i.get(\"elements\") or {}).get(kind) or []\n        if items:\n            print(f\"[{kind}] \" + \"; \".join(f\"{e['ref']} {e['role']} \"\n                                           f\"{e['name'][:30]!r}\"\n                                           for e in items[:12]))\n\n\ndef _prov_brief(d: dict[str, Any]) -> str:\n    \"\"\"Compact provenance for one line of output: origin counts and how many\n    facts are stale (low confidence or never re-confirmed) - S150c.\"\"\"\n    origins = d.get(\"origins\") or {}\n    if not origins and not d.get(\"stale\"):\n        return \"\"\n    return (\"  origin \" + \"/\".join(f\"{k}:{v}\" for k, v in sorted(origins.items()))\n            + f\"  stale:{d.get('stale', 0)}\")\n\n\ndef _r_site(r: dict[str, Any]) -> None:\n    if \"sites\" in r:\n        for s_ in r[\"sites\"]:\n            print(f\"{s_['host']:<40} pages {s_['pages']:<3} states \"\n                  f\"{s_['states']:<3} methods {s_['methods']:<3} attempts \"\n                  f\"{s_['attempts']:<4} recipes {s_['recipes']}  \"\n                  f\"updated {s_.get('updated')}\" + _prov_brief(s_))\n        if not r[\"sites\"]:\n            print(\"no site memory yet\")\n        return\n    print(json.dumps({k: v for k, v in r.items() if k != \"effect_state\"},\n                     ensure_ascii=False, indent=2))\n\n\ndef _r_replay(r: dict[str, Any]) -> None:\n    print(f\"recipe {r.get('recipe')!r} on {r.get('host')}: {r.get('done')} of \"\n          f\"{r.get('steps')} step(s) done\" + (\" (dry run)\" if r.get(\"dry_run\") else \"\")\n          + (f\", stopped at step {r['stopped_at']}\" if r.get(\"stopped_at\") else \"\"))\n    for x in r.get(\"results\") or []:\n        plan = x.get(\"plan\") or {}\n        how = plan.get(\"how\", \"\")\n        extra = plan.get(\"ref\") or plan.get(\"near\") or plan.get(\"text\") or \\\n            plan.get(\"url\") or plan.get(\"why\") or \"\"\n        print(f\"  {x['step']:>2}. {x.get('status'):<8} {x.get('verb'):<8} \"\n              f\"{x.get('target') or ''}  [{how} {extra}]\"\n              + (f\"  interface={x['interface']}\" if x.get(\"interface\") else \"\"))\n        if x.get(\"why\"):\n            print(f\"      {x['why']}\")\n        if x.get(\"error\"):\n            print(f\"      error: {x['error'].get('message')}\")\n\n\ndef _r_know(r: dict[str, Any]) -> None:\n    if r.get(\"answer\") is not None:\n        print(r.get(\"answer\") or r.get(\"note\") or \"\")\n        if r.get(\"error\"):\n            print(f\"error: {r['error']}\")\n        return\n    print(json.dumps({k: v for k, v in r.items() if k != \"effect_state\"},\n                     indent=1, ensure_ascii=False)[:4000])\n\n\ndef _r_video(r: dict[str, Any]) -> None:\n    print(f\"recorded {r.get('frames')} frame(s)\")\n    for k in (\"video\", \"contact_sheet\", \"analysis\"):\n        if r.get(k):\n            print(f\"  {k}: {r[k]}\")\n    print(f\"verdict: {r.get('verdict')}\")\n    for e in r.get(\"errors\") or []:\n        print(f\"  error text at ({e['box'][0]}, {e['box'][1]}): {e['text']}\")\n\n\ndef _r_research(r: dict[str, Any]) -> None:\n    print(f\"query: {r.get('query')!r}  sent to {', '.join(r.get('sent_to') or [])}\")\n    if r.get(\"by_kind\"):\n        print(\"  found: \" + \", \".join(f\"{k} {v}\" for k, v in r[\"by_kind\"].items()))\n    for x in r.get(\"results\") or []:\n        extra = x.get(\"stars\", x.get(\"score\", x.get(\"comments\", \"\")))\n        print(f\"  [{x['source']}] {x['title'][:90]}  ({extra})\\n      {x['url']}\")\n    for src, why in (r.get(\"failures\") or {}).items():\n        print(f\"! {src}: {why}\")\n    if r.get(\"kept_in\"):\n        print(f\"kept in the {r['kept_in']}\")\n\n\ndef _site_command(args: argparse.Namespace, home: Path) -> int:\n    sub_ = args.sitesub\n    if sub_ == \"list\":\n        return emit(call(Method.SITE_LIST.value, session=args.session, home=home), args, _r_site)\n    if sub_ == \"show\":\n        return emit(call(Method.SITE_SHOW.value, {\"host\": args.host},\n                         session=args.session, home=home), args, _r_site)\n    if sub_ == \"check\":\n        return emit(call(Method.SITE_CHECK.value, {\"tab_id\": args.tab_id},\n                         session=args.session, home=home, timeout=300), args, _r_site)\n    if sub_ == \"accept\":\n        return emit(call(Method.SITE_ACCEPT.value,\n                         {\"host\": args.host, \"page\": args.page,\n                          \"state\": args.state}, session=args.session, home=home), args, _r_site)\n    if sub_ == \"forget\":\n        return emit(call(Method.SITE_FORGET.value, {\"host\": args.host},\n                         session=args.session, home=home), args, _r_site)\n    if sub_ == \"recipe\":\n        return emit(call(Method.SITE_RECIPE.value,\n                         {\"host\": args.host, \"name\": args.name},\n                         session=args.session, home=home), args, _r_site)\n    if sub_ == \"replay\":\n        return emit(call(Method.SITE_REPLAY.value,\n                         {\"name\": args.name, \"host\": args.host,\n                          \"tab_id\": args.tab_id, \"dry_run\": args.dry_run,\n                          \"allow_irreversible\": args.allow_irreversible,\n                          \"texts\": args.text},\n                         session=args.session, home=home, timeout=3600), args, _r_replay)\n    if sub_ == \"know\":\n        return emit(call(Method.SITE_KNOW.value,\n                         {\"action\": args.action, \"words\": \" \".join(args.words),\n                          \"answer\": args.answer, \"outcome\": args.outcome,\n                          \"nodes\": args.node},\n                         session=args.session, home=home, timeout=900), args, _r_know)\n    if sub_ == \"page\":\n        return emit(call(Method.SITE_PAGE.value, {\"tab_id\": args.tab_id},\n                         session=args.session, home=home, timeout=120), args, _r_site)\n    if sub_ == \"record\":\n        if args.action == \"start\":\n            if not args.name:\n                print(\"error: `site record start` needs a NAME\", file=sys.stderr)\n                return 1\n            return emit(call(Method.SITE_RECORD_START.value,\n                             {\"name\": args.name}, session=args.session, home=home), args, _r_site)\n        return emit(call(Method.SITE_RECORD_STOP.value, session=args.session, home=home), args,\n                    _r_site)\n    return 1\n\n\ndef _app_command(args: argparse.Namespace, home: Path) -> int:\n    \"\"\"Read local app knowledge; research delegates to the daemon-owned port.\"\"\"\n    from . import appmem, memspace\n    home = memspace.require(home, args.memory)\n    mem = appmem.AppMemory(home)\n    if args.appsub == \"list\":\n        rows = mem.apps()\n        if args.json:\n            print(json.dumps({\"apps\": rows}, ensure_ascii=False, indent=2))\n            return 0\n        for a in rows:\n            print(f\"{a['exe']:<20} {(a.get('display_name') or ''):<24} \"\n                  f\"quirks {a['quirks']:<3} methods {a['methods']:<3} \"\n                  f\"shortcuts {a['shortcuts']:<3} stale {a['stale']}  \"\n                  f\"updated {a.get('updated')}\")\n        if not rows:\n            print(\"no app knowledge yet - `auto app know <exe>` learns an app\")\n        return 0\n    if args.appsub == \"show\":\n        if args.json:\n            print(json.dumps(\n                {\"exe\": appmem.norm_exe(args.exe), \"known\": mem.known(args.exe),\n                 \"memory\": mem.load(args.exe) if mem.known(args.exe) else None},\n                ensure_ascii=False, indent=2))\n            return 0\n        print(mem.summary(args.exe))\n        return 0\n    if args.appsub == \"know\":\n        out = appmem.learn_app(args.exe, home=home)\n        if args.json:\n            print(json.dumps({k: v for k, v in out.items() if k != \"summary\"},\n                             ensure_ascii=False, indent=2))\n            return 0\n        print(f\"learned {out['exe']}\"\n              + (f\" ({out['display_name']})\" if out.get(\"display_name\") else \"\")\n              + (\"  [already known]\" if out.get(\"known_before\") else \"\"))\n        print(f\"  local inventory: \"\n              f\"{'observed' if out.get('observed_locally') else 'not found'}; \"\n              f\"research: {out.get('found', 0)} result(s), \"\n              f\"{out.get('sources', 0)} source(s) kept\")\n        for src, why in (out.get(\"failures\") or {}).items():\n            print(f\"  ! {src}: {why}\")\n        print(out.get(\"summary\") or \"\")\n        print(\"\\nresearch findings are imported and unverified - they show \"\n              \"STALE until a live run confirms them\")\n        return 0\n    return 1\n\n\ndef _dashboard_command(args: argparse.Namespace, home: Path) -> int:\n    from .dashboard import server, shortcut\n    from . import relocation\n    if args.install:\n        root = relocation.checkout_root()\n        if root is None:\n            print(\"error: the shortcuts open a project folder; run this from one\", file=sys.stderr)\n            return 2\n        for path in shortcut.write(root):\n            print(f\"written: {path}\")\n        return 0\n    if args.no_window:\n        srv = server.DashboardServer(home)\n        srv.start(register=False)\n        print(f\"Kgrow.io dashboard: http://127.0.0.1:{srv.port}/#k={srv.key}\")\n        try:\n            while True:\n                time.sleep(3600)\n        except KeyboardInterrupt:\n            srv.close()\n        return 0\n    return server.main(home, reason=args.reason)\n\n\ndef _flow_passes(args: argparse.Namespace, profile: Any, home: Path) -> int:\n    \"\"\"`flow run`, once or `--repeat N` times. Each pass is a fresh runner (the\n    journal keeps decided items decided). A stop file or a signal ends the\n    passes before the next one starts, because each pass clears an old stop\n    file when it begins. Each finished pass is reported to the dashboard.\"\"\"\n    from .workflow import _SIGNALLED, FlowRunner, stop_file_for\n    total = max(1, int(getattr(args, \"repeat\", 1) or 1))\n    # Known to the dashboard even when started from a terminal: Stop tells it to\n    # wind up, Reset ends it (runcontrol.py). A run without a daemon goes on.\n    try:\n        first = FlowRunner(profile, home=home, session_tag=args.tag, dry_run=args.dry_run)\n        call(\"_run.flow_register\", {\"pid\": os.getpid(), \"profile\": profile.name,\n                                    \"journal\": str(first.journal), \"file\": str(profile.path or \"\")},\n             home=home, start_if_missing=False, timeout=10)\n    except Exception:                               # noqa: BLE001 - the dashboard is a view\n        pass\n    for done in range(total):\n        if done and (_SIGNALLED or stop_file_for(home, profile.name).exists()):\n            print(f\"stopped before pass {done + 1} of {total}\")\n            break\n        runner = FlowRunner(profile, home=home, session_tag=args.tag, dry_run=args.dry_run)\n        out = runner.run(minutes=args.minutes, max_items=args.max_items,\n                         max_acted=getattr(args, \"max_acted\", 0))\n        print(f\"\\n{out['examined']} examined, {out['acted']} acted  journal: {out['journal']}\"\n              + (f\"  (pass {done + 1} of {total})\" if total > 1 else \"\"))\n        if out.get(\"stopped\"):\n            print(f\"ended early: {out['stopped']}\")\n        if total > 1:\n            try:\n                call(\"_run.progress\", {\"name\": profile.name, \"done\": done + 1, \"total\": total},\n                     home=home, start_if_missing=False, timeout=10)\n            except Exception:                       # noqa: BLE001 - the dashboard is a view\n                pass\n        if _SIGNALLED or runner.stop_file.exists():\n            break\n    return 0\n\n\ndef _r_run(r: dict[str, Any]) -> None:\n    run = r.get(\"run\") or {}\n    print(f\"state: {r.get('state')}\" + (f\"  run: {run.get('kind')} {run.get('name') or ''}\".rstrip() if run else\n                                        \"  no run\"))\n    if r.get(\"always_allow\"):\n        print(\"always allow: on for this run\")\n    for item in r.get(\"pending\") or []:\n        print(f\"waiting for you: {item.get('detail')}  (auto approve {item.get('token')})\")\n    if r.get(\"approvals_declined\"):\n        print(f\"approvals declined: {r['approvals_declined']}\")\n    for name in r.get(\"flows_told_to_stop\") or []:\n        print(f\"flow told to stop: {name}\")\n    if r.get(\"progress\"):\n        prog = r[\"progress\"]\n        print(f\"repetitions: {prog['done']} of {prog['total']} done ({prog['name']})\")\n    elif r.get(\"repeat\", 1) != 1:\n        print(f\"repeat: the next saved path runs {r['repeat']} times\")\n    if \"sessions_closed\" in r:\n        print(f\"reset: {len(r.get('flows_ended') or [])} flow process(es), \"\n              f\"{len(r.get('programs_ended') or [])} program(s), {len(r.get('watchdogs_ended') or [])} \"\n              f\"watchdog(s) ended; {len(r.get('windows_closed') or [])} window(s), \"\n              f\"{len(r.get('tabs_closed') or [])} tab(s), {len(r['sessions_closed'])} session(s) closed\"\n              + (f\", still busy: {', '.join(r['sessions_still_busy'])}\" if r.get(\"sessions_still_busy\") else \"\"))\n        if r.get(\"sessions_left_running\"):\n            print(\"left running (not this run's): \" + \", \".join(r[\"sessions_left_running\"]))\n        if r.get(\"view_kept\"):\n            print(f\"view kept: {r['view_kept']}\")\n        for title in r.get(\"windows_kept_unsaved\") or []:\n            print(f\"left open (unsaved changes): {title}\")\n\n\ndef _detect_move(home: Path) -> None:\n    \"\"\"Every command, from any terminal or agent: when the project folder was\n    moved (its recorded location no longer holds it), repair the outside links\n    before running. A copy is left alone. Reports on stderr; never blocks.\"\"\"\n    from . import relocation\n    result = relocation.auto_repair(home, relocation.checkout_root())\n    if not result or result.get(\"moved\") is False:\n        return\n    if result.get(\"moved\"):\n        print(f\"project folder moved from {result['from']} to {result['root']}\", file=sys.stderr)\n        for line in result.get(\"repaired\", []):\n            print(f\"  repaired: {line}\", file=sys.stderr)\n        for row in result.get(\"failed\", []):\n            print(f\"  NOT repaired: {row['check']}: {row['error']}\", file=sys.stderr)\n    else:\n        print(result.get(\"notice\", \"\"), file=sys.stderr)\n\n\ndef _relocate_command(args: argparse.Namespace, home: Path) -> int:\n    \"\"\"Local on purpose: after a move the daemon may be the thing that is broken.\"\"\"\n    from . import relocation\n    root = relocation.checkout_root()\n    if root is None:\n        print(\"error: `auto relocate` runs from a project folder, not an installed runtime\", file=sys.stderr)\n        return 1\n    if args.prepare:\n        r = relocation.prepare(root, home)\n    elif args.apply:\n        r = relocation.repair(root, home)\n    else:\n        r = relocation.main_report(root, home)\n    if args.json:\n        print(json.dumps(r, ensure_ascii=False, indent=2))\n        return 0 if (r.get(\"ready\", True) and not r.get(\"failed\")) else 1\n    print(f\"project folder: {r['root']}\")\n    if args.prepare:\n        print(f\"  daemon: {r['daemon']}\")\n        for row in r[\"still_running\"]:\n            print(f\"  still running: pid {row['pid']} {row['name']}  ({row['path']})\")\n        print(r[\"next\"])\n        return 0 if r[\"ready\"] else 1\n    for line in r.get(\"repaired\", []):\n        print(f\"  repaired: {line}\")\n    for row in r.get(\"failed\", []):\n        print(f\"  NOT repaired: {row['check']}: {row['error']}\")\n    bad = 0\n    for f in r[\"findings\"]:\n        bad += not f[\"ok\"]\n        print(f\"  [{'ok  ' if f['ok'] else 'FIX '}] {f['check']:<28} {f['detail']}\")\n        if not f[\"ok\"] and f.get(\"fix\"):\n            print(f\"         fix: {f['fix']}\")\n    if bad and not args.apply:\n        print(\"\\nrun Register-Project.cmd (or `auto relocate --apply`) to repair \"\n              \"(a changed file is copied to *.before-relocate first)\")\n    return 1 if bad or r.get(\"failed\") else 0\n\n\ndef _mind_command(args: argparse.Namespace, home: Path) -> int:\n    \"\"\"The mind is local: it reads the memory files under the home and a\n    small state file. No daemon round-trip — the same shape as `app`.\"\"\"\n    from . import memspace\n    from .mind import Mind\n    mind = Mind(memspace.require(home, args.memory), history_home=home,\n                space=memspace.check_name(args.memory))\n    if args.mindsub == \"stats\":\n        print(json.dumps(mind.stats(), ensure_ascii=False, indent=2))\n        return 0\n    if args.mindsub == \"recall\":\n        rows = mind.recall(args.query, k=args.k)\n        if args.json:\n            print(json.dumps({\"query\": args.query, \"memories\": [\n                {\"id\": d.id, \"source\": f\"{d.source_kind}:{d.source}\",\n                 \"kind\": d.kind, \"score\": round(s, 3),\n                 \"confidence\": d.confidence, \"weight\": mind.weight(d.id),\n                 \"text\": d.text} for d, s in rows]},\n                ensure_ascii=False, indent=2))\n            return 0\n        if not rows:\n            print(\"nothing recalled - the mind is empty or the query \"\n                  \"shares no words with any memory\")\n            return 0\n        for d, s in rows:\n            w = mind.weight(d.id)\n            mark = f\" w{w:.2f}\" if abs(w - 1.0) > 0.01 else \"\"\n            print(f\"{s:0.3f}{mark}  [{d.source_kind}:{d.source}] \"\n                  f\"{d.kind}: {d.text[:180]}\")\n            print(f\"        id: {d.id}\")\n        return 0\n    if args.mindsub == \"families\":\n        fams = mind.families()\n        if args.json:\n            print(json.dumps({\"families\": fams}, ensure_ascii=False,\n                             indent=2))\n            return 0\n        if not fams:\n            print(\"not enough memories to cluster yet\")\n            return 0\n        for i, f in enumerate(fams):\n            print(f\"family {i}: {f['name']}\")\n            for m in f[\"members\"]:\n                print(f\"    {m}\")\n        return 0\n    if args.mindsub == \"note\":\n        w = mind.note_outcome(args.doc_id, args.outcome == \"ok\")\n        print(f\"{args.doc_id} -> weight {w:.2f}\")\n        return 0\n    return 1\n\n\ndef _rb_command(args: argparse.Namespace, home: Path) -> int:\n    \"\"\"Drive the user's real browser — through the daemon, not around it.\n\n    This used to call the bridge directly from the CLI. That skipped the\n    permission engine and the audit log entirely, on the one surface that\n    reaches the user's signed-in mail, HR system and bank. Routing it through\n    `call()` puts it behind the same gate as every other verb.\n\n    The command shapes are unchanged on purpose: `auto rb observe` still takes\n    no `--session`, because the rb verbs are registered sessionless and the\n    per-tab ref store lives on the daemon, which outlives individual CLI calls.\n\n    `install` / `uninstall` stay local: they write a registry key and a host\n    manifest for the *user*, and must work before any daemon exists.\n    \"\"\"\n    from . import nmhost\n\n    if args.rbsub == \"ensure\":\n        from .browser_setup import prepare\n        result = prepare(args.browser, home, args.profile)\n        print(json.dumps(result, indent=2))\n        return 0 if result[\"status\"] == \"CONNECTED\" else 2\n    if args.rbsub == \"install\":\n        print(json.dumps(nmhost.install(args.extension_id, browser=args.browser), indent=2))\n        print(\"\\nNow reload the extension in your browser's extensions page so it \"\n              \"reconnects to the host.\")\n        return 0\n    if args.rbsub == \"uninstall\":\n        print(json.dumps(nmhost.uninstall(browser=args.browser), indent=2))\n        return 0\n\n    tab = getattr(args, \"tab_id\", None)\n    table: dict[str, tuple[str, dict[str, Any], Any]] = {\n        \"status\":   (Method.RB_STATUS.value, {}, _r_rb_status),\n        \"tabs\":     (Method.RB_TABS.value, {}, _r_rb_tabs),\n        \"open\":     (Method.RB_OPEN.value, {\"url\": getattr(args, \"url\", \"\")},\n                     _r_action),\n        \"activate\": (Method.RB_ACTIVATE.value, {\"tab_id\": tab}, _r_action),\n        \"navigate\": (Method.RB_NAVIGATE.value,\n                     {\"url\": getattr(args, \"url\", \"\"), \"tab_id\": tab},\n                     _r_action),\n        \"observe\":  (Method.RB_OBSERVE.value,\n                     {\"tab_id\": tab,\n                      \"max_tokens\": getattr(args, \"max_tokens\", None),\n                      \"fallback\": not getattr(args, \"no_fallback\", False),\n                      \"ocr\": getattr(args, \"ocr\", False)},\n                     _r_rb_observe),\n        \"locate\":   (Method.RB_LOCATE.value,\n                     {\"near\": getattr(args, \"near\", \"\"),\n                      \"pick\": getattr(args, \"pick\", None),\n                      \"nth\": getattr(args, \"nth\", 1), \"tab_id\": tab},\n                     _r_locate),\n        \"click\":    (Method.RB_CLICK.value,\n                     {\"ref\": getattr(args, \"ref\", \"\"), \"tab_id\": tab},\n                     _r_action),\n        \"type\":     (Method.RB_TYPE.value,\n                     {\"text\": getattr(args, \"text\", \"\"),\n                      \"ref\": getattr(args, \"ref\", None), \"tab_id\": tab},\n                     _r_action),\n        \"key\":      (Method.RB_KEY.value,\n                     {\"key\": getattr(args, \"key\", \"\"), \"tab_id\": tab},\n                     _r_action),\n        \"upload\":   (Method.RB_UPLOAD.value,\n                     {\"ref\": getattr(args, \"ref\", \"\"),\n                      \"files\": getattr(args, \"file\", []), \"tab_id\": tab},\n                     _r_action),\n        \"reload\":   (Method.RB_RELOAD.value, {\"tab_id\": tab}, _r_action),\n        \"wait\":     (Method.RB_WAIT.value,\n                     {\"name\": getattr(args, \"name\", \"\"),\n                      \"role\": getattr(args, \"role\", None),\n                      \"timeout\": getattr(args, \"timeout\", 20), \"tab_id\": tab},\n                     _r_action),\n        \"close\":    (Method.RB_CLOSE.value, {\"tab_id\": tab}, _r_action),\n        \"reset\":    (Method.RB_RESET.value, {}, _r_action),\n        \"screenshot\": (Method.RB_SCREENSHOT.value,\n                       {\"tab_id\": tab, \"out\": getattr(args, \"out\", None),\n                        \"with_overlay\": getattr(args, \"with_overlay\", False)},\n                       _r_action),\n        \"ocr\":      (Method.RB_OCR.value,\n                     {\"tab_id\": tab, \"find\": getattr(args, \"find\", None),\n                      \"nth\": getattr(args, \"nth\", 1),\n                      \"lang\": getattr(args, \"lang\", None)}, _r_ocr),\n        \"click-at\": (Method.RB_CLICK_AT.value,\n                     {\"x\": getattr(args, \"x\", 0), \"y\": getattr(args, \"y\", 0),\n                      \"dry\": getattr(args, \"dry\", False), \"tab_id\": tab},\n                     _r_click_at),\n        \"act\":      (Method.RB_ACT.value,\n                     {\"ref\": getattr(args, \"ref\", None),\n                      \"text\": getattr(args, \"text\", None),\n                      \"nth\": getattr(args, \"nth\", 1),\n                      \"methods\": getattr(args, \"method\", None),\n                      \"patience\": getattr(args, \"patience\", None),\n                      \"irreversible\": getattr(args, \"irreversible\", False),\n                      \"no_reload\": getattr(args, \"no_reload\", False),\n                      \"no_visual\": getattr(args, \"no_visual\", False),\n                      \"expect_appear\": getattr(args, \"expect_appear\", []),\n                      \"expect_gone\": getattr(args, \"expect_gone\", []),\n                      \"near\": getattr(args, \"near\", None),\n                      \"pick\": getattr(args, \"pick\", None),\n                      \"expect_download\": getattr(args, \"expect_download\", None),\n                      \"no_ensure\": getattr(args, \"no_ensure\", False),\n                      \"accept_weak\": getattr(args, \"accept_weak\", False),\n                      \"tab_id\": tab}, _r_act),\n        \"video\":    (Method.RB_VIDEO.value,\n                     {\"tab_id\": tab, \"seconds\": getattr(args, \"seconds\", 10.0),\n                      \"title\": getattr(args, \"title\", \"recording\"),\n                      \"with_overlay\": getattr(args, \"with_overlay\", False)},\n                     _r_video),\n        \"analyse\":  (Method.RB_ANALYSE.value,\n                     {\"tab_id\": tab, \"ocr\": not getattr(args, \"no_ocr\", False)},\n                     _r_interface),\n        \"selfreload\": (Method.RB_SELFRELOAD.value, {}, _r_action),\n    }\n    if args.rbsub not in table:\n        print(f\"error: unknown rb command {args.rbsub!r}\", file=sys.stderr)\n        return 1\n    method, params, renderer = table[args.rbsub]\n    timeout = float(getattr(args, \"timeout\", 0) or 0) + 300\n    if args.rbsub in (\"act\", \"analyse\", \"ocr\", \"video\"):\n        # A ladder can try four methods twice and reload once; OCR runs the\n        # Windows engine. Neither fits the default budget of one click.\n        timeout += 600\n    return emit(call(method, params, session=args.session, home=home, timeout=timeout),\n                args, renderer)\n\n\ndef _set_mode_locally(home: Path, args: argparse.Namespace) -> int:\n    if args.key == \"desktop-interactive-fallback\":\n        from .safety.permissions import load_policy, save_policy\n        value = str(args.value).lower()\n        if value not in (\"on\", \"off\"):\n            print(\"error: expected on or off\", file=sys.stderr)\n            return 1\n        policy = load_policy(home)\n        policy.desktop_interactive_fallback = value == \"on\"\n        save_policy(home, policy)\n        print(f\"desktop-interactive-fallback: {value}\")\n        return 0\n    if args.key == \"default-browser\":\n        return _set_default_browser_locally(home, args)\n    if args.key == \"steal-focus\":\n        return _set_steal_focus_locally(home, args)\n    from .safety.permissions import PermissionMode, load_policy, save_policy\n    try:\n        mode = PermissionMode(args.value)\n    except ValueError:\n        print(f\"error: unknown mode {args.value!r}\", file=sys.stderr)\n        print(\"hint: use strict, guarded or full.\", file=sys.stderr)\n        return 1\n    policy = load_policy(home)\n    previous = policy.mode.value\n    policy.mode = mode\n    save_policy(home, policy)\n    print(f\"permission mode: {previous} -> {mode.value}\")\n    if mode is PermissionMode.FULL:\n        print(\"warning: 'full' runs every action without asking. Nothing \"\n              \"else will stop a mistake.\")\n    return 0\n\n\ndef _set_steal_focus_locally(home: Path, args: argparse.Namespace) -> int:\n    \"\"\"Whether the tool may take the desktop foreground while it works.\n\n    Off means the browser tab is activated but its window is never raised,\n    and any desktop action that genuinely needs the foreground — real mouse\n    input, synthetic keystrokes, a region screenshot — hands it straight\n    back. On restores the old behaviour, which is worth having when a page\n    will not stay responsive without focus.\n\n    Written from the shell, like the permission mode, because it is the\n    user's call and not the agent's.\n    \"\"\"\n    from .safety.permissions import load_policy, save_policy\n    value = str(args.value).strip().lower()\n    if value in (\"on\", \"true\", \"yes\", \"1\"):\n        want = True\n    elif value in (\"off\", \"false\", \"no\", \"0\"):\n        want = False\n    else:\n        print(f\"error: expected on or off, got {args.value!r}\", file=sys.stderr)\n        return 1\n    policy = load_policy(home)\n    before = bool(getattr(policy, \"steal_focus\", False))\n    policy.steal_focus = want\n    save_policy(home, policy)\n    print(f\"steal-focus: {'on' if before else 'off'} -> \"\n          f\"{'on' if want else 'off'}\")\n    if want:\n        print(\"  the tool will raise windows while it works; whatever you are \"\n              \"doing will be buried\")\n    else:\n        print(\"  the tool stays out of the way: browser tabs are activated \"\n              \"without raising their window, and the desktop foreground is \"\n              \"handed back after any action that needed it\")\n    print(\"  (the running daemon picks this up on its next request)\")\n    return 0\n\n\ndef _set_default_browser_locally(home: Path,\n                                 args: argparse.Namespace) -> int:\n    \"\"\"Pin which browser `browser open` uses. Like the permission mode, this\n    is written from the shell — the agent asks the user and opens with\n    `--browser <choice>` per task, but the standing default stays user-owned.\n    \"\"\"\n    from .browser.cdp import BROWSERS, available_browsers\n    from .safety.permissions import load_policy, save_policy\n    value = args.value.strip()\n    known = value.lower() in BROWSERS or value.lower() in (\"none\", \"clear\")\n    if not known:\n        from pathlib import Path as _P\n        if not (_P(value).exists() and value.lower().endswith(\".exe\")):\n            found = \", \".join(b[\"name\"] for b in available_browsers()) or \"none\"\n            print(f\"error: unknown browser {value!r}\", file=sys.stderr)\n            print(f\"hint: use one of {found}, a full path to a Chromium \"\n                  f\"browser .exe, or 'none' to clear the default.\",\n                  file=sys.stderr)\n            return 1\n    policy = load_policy(home)\n    previous = policy.default_browser\n    policy.default_browser = None if value.lower() in (\"none\", \"clear\") else value\n    save_policy(home, policy)\n    print(f\"default browser: {previous or '(preference order)'} -> \"\n          f\"{policy.default_browser or '(preference order)'}\")\n    return 0\n\n\ndef _answer(home: Path, args: argparse.Namespace) -> int:\n    \"\"\"Approve/deny is answered against the daemon's in-memory broker.\"\"\"\n    ep = read_endpoint(home)\n    if not ep:\n        print(\"error: no daemon running\", file=sys.stderr)\n        return 2\n    granted = args.cmd == \"approve\"\n    frame = {\"id\": \"ans\", \"method\": \"system.status\", \"token\": ep[\"token\"],\n             \"params\": {}}\n    # The broker is in-process; answering goes through a dedicated control\n    # frame so that no handler can be tricked into self-approval.\n    frame[\"method\"] = \"_confirm.answer\"\n    frame[\"params\"] = {\"token\": args.token, \"granted\": granted}\n    with socket.create_connection((\"127.0.0.1\", ep[\"port\"]), 10) as sk:\n        sk.sendall((json.dumps(frame) + \"\\n\").encode())\n        sk.settimeout(15)\n        line = sk.makefile(\"rb\").readline()\n    resp: dict[str, Any] = json.loads(line.decode(\"utf-8\")) if line else {\"ok\": False}\n    if resp.get(\"ok\"):\n        print(f\"{'approved' if granted else 'denied'} {args.token}\")\n        return 0\n    print(f\"error: {(resp.get('error') or {}).get('message', 'unknown token')}\",\n          file=sys.stderr)\n    return 1\n\n\nif __name__ == \"__main__\":\n    raise SystemExit(main())\n");
